window.HB_TR["daniel"]["ks"]=["1.\\tیہوداہُک بادشاہ یہوویاقیم سٕندِ دورِ حکومتہٕ کِس تریمہِ ؤریس مَنٛز آو بابلُک بادشاہ نبوکدنضر یروشلمس مَنٛز تہٕ کوٚرُن اتھ محاصرٕ۔\n2. تہٕ خداوند دِیُت یہوداہُک بادشاہ یہویاکیم پننِس اتھس منز، یُس خدایہ سٕندِس گرٕ سٕندِس بانہٕ سٍتـ̡ ہُند حِصہٕ ہیتھ دِیُت، یُس سُہ شِنار کِس سرزمینس مَنٛز پننِس خدایہ سٕندِس گرس نِش نِیو۔ تہٕ أمۍ أنۍ بانہٕ پننِس خدایہ سٕنٛدِس خزانہٕ خانس منٛز۔\n3.\\tتہٕ بادشاہن کٔر پننین خواجہ سراؤں ہٕندِس مٲلکِس اشپینازس سٍتـ̡ کتھ زِ سُہ گژھہِ اسرٲیلٕکۍ اولاد تہٕ بادشاہ سٕندِس اولادس تہٕ شہزادن ہٕندِس نِش اَننہٕ۔\n4. تِم شُرۍ یِمن مَنٛز نہٕ کانہہ عیب آسہِ، مگر یِمن منز کانہہ عیب آسہِ، مگر یِمن ہٕندِس سٍتـ̡ ہوشیار تہٕ علمس مَنٛز ہوشیار آسہِ، تہٕ یِمن سٍتـ̡ بادشاہ سٕندِس محلس مَنٛز کھڑا گژھنٕچ صلٲحیت آسہِ، تہٕ یِمن ہٕندِس سٍتـ̡ تِمن ہٕندِس محلس مَنٛز کھڑا گژھنٕچ صلٲحیت آسہِ، تہٕ یِمن ہٕندِس علمس تہٕ زبان ہیچھناوٕنـ̡ آسہِ۔\n5.\\tتہٕ بادشاہن دِژ تِمن بادشاہ سُند ماز تہٕ شرابُک دوہ دِنہٕ آمُت، یُس سُہ چیٚوان اوس، یُتھ زن تِمن تریہ ؤری پرورش دِنہٕ یُتھ تِم بادشاہس برونہہ کنہِ کھڑا گژھن۔ {شراب...: ہیب۔ تٔمۍ سٕندِ شرابُک شراب}\n6.\\tیِمن مَنٛز اوس یہوداہ، دانیال، حنانیہ، مشائل تہٕ عزریاہ سٕندِس اولادَس مَنٛز شٲمِل:\n7.\\tیٔمِس کُنہِ سٍتـ̡ دِژمُت چھُ۔ تہٕ حنانیاہ سٕندِس شادرک سٕندِس سٍتـ̡ ۔ تہٕ مِشایِل سٕندِس مِشالس سٍتـ̡ ۔ تہٕ عابدنیگو کِس عزریاہس سٍتۍ۔\n8. مگر دانیال اوس پننِس دِلس منز ارادہ کوٚرمت زِ سُہ کرِ نہٕ بادشاہ سٕندِس مازس سٍتـ̡ پانس ناپاک کرنہٕ، تہٕ نہ چیٚنہٕ وٲلِس شرابہٕ سٍتـ̡ ناپاک کرنہٕ۔\n9. وۅنۍ اوس خدایہ دانیالس خواجہ سراؤں ہٕندِس شہزادس سٍتـ̡ احسان تہٕ نرم محبتس مَنٛز انمُت۔\n10.\\tتہٕ کُنہِ شُرِ سٍتـ̡ چُھہ تُہٕندِس بُتھِس سٍتـ̡ دِژمُت، یێمہِ سٍتـ̡ چُھہ تُہُند ماز تہٕ چُھہ چُھہ تُہٕندِس بُتھِس سٍتـ̡ زیادٕ خۅش سپدان۔ تیلہ کٔرِکھ ژیہ بادشاہس کُن میون کلہ خطرس منز تراوُن۔ {بدتر...: ہیب۔ sadder} {sort: or, term, or, continuance?}\n11.\\tتێلہِ ووٚن دانیال میلزارس یُس کُنہِ خواجہ سرا ہٕندِس شہزادن دانیال، حنانیہ، مشائل تہٕ عزریاہ ہٕندِس شہزادس پیٹھ مقرر کورمُت اوس، {میلزار: یا، سُہ سٍتـ̡\n12. پنٕنۍ خادم، بہٕ چھُس ژےٚ دَہ دۅہہٕ ثٲبت کٔرِتھ۔ تہٕ تِم دِن اسہِ کھٮ۪نہٕ خٲطرٕ دال تہٕ چنہٕ خٲطرٕ آب دِنہٕ۔ {نبض: ہیب۔ نبض ہُند} {کھٮ۪نہٕ خٲطرٕ...: ہیب۔ تاکہ أسۍ ہیکون کھٮ۪تھ وغیرہ}\n13.\\tتیلہِ گژھہِ سانہِ بُتھ تہٕ بادشاہ سٕندِس مازُک حصہٕ کھٮ۪نہٕ والٮ۪ن شُرین ہُند بُتھ وُچھُن، تہٕ یُتھ ژے وُچھِو، پَنٕنٮ۪ن خادمَن سٍتـ̡ کٔرِو سٍتـ̡\n14.\\tتێلہِ کٔر تِمن اتھ معاملس منز رضامندی تہٕ دَہ دۅہ ثٲبت کٔرِتھ۔\n15.\\tتہٕ دہن دۅہن پتہٕ گٔیہِ تِہُند بُتھ سارِنٕے شُرین کھٮ۪نہٕ کھۅتہٕ مازس منز زیادٕ گور تہٕ موٚٹۍ باسان۔\n16. یِتھٕ پٲٹھۍ نِش میلزارن تِہُند مازُک حصہٕ تہٕ شراب یُس تِم چیٚنہٕ یُن۔ تہٕ دِژ تمن نبض۔\n17.\\tیِمن ژۅن شُرین ہُند تعلق چھُ خداین تِمن سارِنٕے ہیچھنُک تہٕ حکمت ہُند علم تہٕ ہُنر دِژمُت، تہٕ دانیالس اوس سارِنٕے وژنن تہٕ خوابن مَنٛز سمجھ۔ {دانیال...: یا، تمۍ کٔر دانیالس سمجھان}\n18.\\tوۅنۍ ییلہ بادشاہن ووٚنمُت اوس زِ تِم اَننہٕ یِن، تیلہِ أنۍ تِم نبوکدنضرس برونہہ کُن۔\n19. تہٕ بادشاہن کٔر تِمن سٍتـ̡ رٲبطہٕ۔ تہٕ یِمن سارِنٕے مَنٛز آو نہٕ دٲنیال، حنانیہ، مشائل تہٕ عزریاہ ہِش کانہہ تہِ لبنہٕ، لہذا گٔیہِ تِم بادشاہس برونہہ کُن۔\n20.\\tتہٕ حکمت ہٕندِس سارِنٕے معاملس مَنٛز، یُس بادشاہن تِمن مُتلق پرژھہٕ گٲر کٔر، تٔمِس لٔب تِم سارِنٕے جادوگرن تہٕ نجومی نِش دَہ گنہٕ بہتر۔ {حکمت...: ہیب۔ فہم ہٕنٛز حکمت}\n21. تہٕ دانیال رود بادشاہ سائرس سٕندِس گۄڈنِکِس ؤریس تام جٲری۔","1. تہٕ نبوکدنضر سٕندِ دورِ حکومتہٕ کِس دٔیمِس ؤریس مَنٛز وُچھ نبوکدنضر خواب، یَتھ سٍتـ̡ تٔمِس روح پریشان گوو، تہٕ تٔمِس نِش نِندرِ ہٕندِس نِش پھُٹ۔\n2. پتہٕ دِیُت بادشاہن حُکُم زِ سُہ کرِ جادوگرن، نجومی، تہٕ جادوگرن تہٕ کلدینن بُلاونہٕ خٲطرٕ، تاکہ بادشاہس پنُن خواب ہاونہٕ۔ چنانچہ آیہ تِم بادشاہس برونہہ کنہِ کھڑا۔\n3.\\tتہٕ بادشاہن ووٚن تِمن زِ میہ چھہ اکھ خواب وچھمُت، تہٕ میون روح اوس یہ خواب زاننہ مۅکھہ پریشان۔\n4.\\tاَمہ پتہٕ کٔرِو کلدان بادشاہس سٍتـ̡ کتھ زِ اے بادشاہ، ہمیشہٕ زندٕ روزُن: پننین خدمتگارن وَن خواب، تہٕ أسۍ ہٲوِو تعبیر۔ {اے بادشاہ...: (چالدی، باب ستھ کِس اندس تام}\n5.\\tبادشاہن دیُت جواب تہٕ وونُن چالدیَن زِ یہِ چیز چُھہ میانہِ نِش ژٔلِتھ: یێلہِ نہٕ ژے میہ یہ خواب، اَمہ سٍتـ̡ تعبیر کرنہٕ سٍتـ̡ یِن ژٔٹِتھ ژٹنہٕ تہٕ تُہند گرٕ یِن گُرِ بَناونہٕ۔ {کٹ ...: چالڈی، بٔنِتھ ٹُکرٕ}\n6.\\tمگر اگر ژیہ خواب تہٕ امچ تعبیر ہٲوِو، تیلہِ میلہِ میانہِ طرفہٕ تحفہٕ تہٕ انعام تہٕ بٔڈ عزت، لہذا ہٲوِو مے خواب، تہٕ امچ تعبیر۔ {انعام: یا، فیس}\n7.\\tتِمو دِژ دُبارٕ جواب تہٕ وونُن، بادشاہ وَنُن پننین خادَن ہُند خواب، تہٕ أسۍ ہٲوِو اَمیُک تعبیر۔\n8.\\tبادشاہن دیُت جواب تہٕ وونُن، بہٕ چُھس پَکہٕ پٲٹھـ̡ پَے زِ ژے میلہِ وَقٕت، تِکیازِ ژے چُھہ وُچھان زِ یہِ چیز چُھہ میانہِ نِش ژٔلِمُت۔ {gain: chaldee, buy}\n9.\\tمگر اگر نہٕ ژے میہ خوابس سٍتـ̡ ظٲہر کٔرِو، {مگر چُھہ} چُھہ ژے خٲطرٕ اَکھ حکم: کیازِ ژے چُھہ میانہِ برونہہ کُن بولنہٕ خٲطرٕ اپُز تہٕ بدکار لفظ تیار کورمُت، یوتام نہٕ وقت بدلاونہٕ ییہِ، تێلہِ وَن مے خواب، تہٕ بہٕ گژھہِ معلوم زِ ژٕ ہٲوِکھ مے امیُک تعبیر ہٲوِتھ۔\n10.\\tکالدِیو دِژ بادشاہس برونہہ کُن جواب تہٕ وونُن، زمینس پیٹھ چُھنہٕ کانہہ انسان یُس بادشاہ سُند معاملہٕ ہٲوِتھ ہیکہِ، لہٰذا چُھنہٕ کانہہ بادشاہ، مالک، تہٕ نہ حکمران، یُس کُنہِ تہِ جادوگر، یا نجومی، یا کلدینس نِش یِتھٕ کتھہٕ پرژھہِ۔\n11. تہٕ یہِ چُھ اَکھ نایاب چیز یُس بادشاہس ضروُرت چُھ، تہٕ بییہ کانہہ تہِ چُھ نہٕ یُس بادشاہس برونہہ کُن ہٲوِتھ، سوائے دیوتاہن ہٕندِ، یٔمۍ سُند روزن ماز آسہِ نہٕ۔\n12.\\tاَمہِ وجہہ کِنۍ گوٚو بادشاہ شَرارتہٕ تہٕ سٮ۪ٹھاہ شرارت تہٕ دِتُن بابل کین سارِنٕے دانشمندن تباہ کرنُک حُکُم۔\n13.\\tتہٕ حکم دِیُت زِ عقلمند گژھن مارنہٕ یُن۔ تہٕ تِمو ژھانڈ دانیال تہٕ تٔمۍ سٕندِس سٲتھی مارنہٕ خٲطرٕ۔\n14. پتہٕ دِیُت دانیال بادشاہ سٕندِس محافظس ہٕندِس کپتانس مشورٕ تہٕ دانشمندی سٍتـ̡ جواب، یُس بابل کین دانشمندن ہُند قتل کرنہٕ خٲطرٕ درٛامُت اوس: {جواب...: چالدی، واپس} {کپتان...: یا، چیف مارشل: چالدی، جلادن ہُند سردار، یا، ذبح}\n15.\\tتٔمۍ دیُت جواب تہٕ وونُن بادشاہ سٕندِس کپتانس آریوچس زِ بادشاہ سٕندِ طرفہٕ کیازِ چُھہ یہِ حکم {یُت} جلدی کرنہٕ آمُت؟ تمہ پتہ کٔر اریوچن دانیالس یہ کتھ خبر۔\n16.\\tتێلہِ گۆو دانیال اژان تہ بادشاہس منگن زِ سُہ دِیہِ تس وقت تہٕ سُہ کرِ بادشاہس تشریح ہاونہٕ۔\n17.\\tتێلہِ گۆو دانیال پننِس گرس منز، تہٕ بێیہِ ہٕندِس سٲتھین حنانیہ، مشائل تہٕ عزریاہ سٍتـ̡ یہِ کتھ زان۔\n18. زِ تِم کرَن اتھ رازس مُتعلِق آسمانہٕ کِس خدایہ سٕنزِ رحمتٕچ خواہش۔ زِ دانیال تہٕ تٔمۍ سٕندِس سٲتھی گژھن نہٕ بابل کین باقٕے دانشمندن سٍتـ̡ مارٕنـ̡ ۔ {خدایہ سٕندِ: کلدی، خدایہ سٕندِ برونہہ} {سہ دانیال...: یا یہ زِ تم پزِ نہٕ دانیال تباہ کرُن، وغیرہ}\n19.\\tاَمہ پتہٕ آو دٲلِس رٲژ ہٕندِس وژنس منز دٲلِس سٍتـ̡ راز ظٲہر کرنہٕ۔ پتہٕ کٔر دانیالن آسمانہٕ کِس خدایس برکت۔\n20.\\tدانیالن دیُت جواب تہٕ وونُن، خدایہ سُند ناو آسُن ہمیشہ ہمیشہ خٲطرٕ بابرکت آسُن، تکیازِ حکمت تہٕ طاقت چھے تٔمِس:\n21. تہٕ سُہ چُھ زمانہٕ تہٕ موسم بدلاوان: سُہ چُھ بادشاہن ہٹاوان تہٕ بادشاہن بِہناوان چُھ: سُہ چُھ دانشمندن حکمت دِوان، تہٕ تِمن علم دِوان یُس سمجھ زانان چُھ:\n22. سُہ چُھ سرٛوٚن تہٕ رازٕ چیزن ظٲہر کران: سُہ چُھ زانان زِ اوندِپِس مَنٛز کیا چُھ، تہٕ گاش چُھ أمِس سٍتـ̡ روزان۔\n23. بہٕ چُھس تُہند شُکر ادا کران تہٕ تُہٕنز تعریف کَران، اے میانین آباؤ اجدادن ہُند خدا، یٔمۍ مےٚ حکمت تہٕ طاقت دِژمٕژ چھےٚ، تہٕ وُنۍ چُھس مےٚ آگاہ کورمُت یُس أسۍ ژے نِش یژھان چھُ، کیازِ ژے چُھس اسہِ بادشاہ سُند معاملہٕ زانمُت۔\n24. تێمہِ کِنۍ گۆو دانیال اریوخس نِش، یُس بادشاہن بابل کین دانشمندن تباہ کرنُک حکم اوس دِژمُت: سُہ گۆو تہٕ وونُن أمِس یِتھٕ پٲٹھۍ۔ بابل کِس دانشمندَس کٔرِو نہٕ تباہ کٔرِتھ، مے أنِو بادشاہس برونہہ کُن، تہٕ بہٕ ہاوٕ بادشاہس تشریح۔\n25.\\tاَمہِ پتہٕ اوٚن آریوخ دٲنِیال بادشاہس برونہہ کُن تہٕ وونُن أمِس یِتھٕ پٲٹھۍ زِ مے لوٚب یہوداہ کِس قٲدِس منز اکھ شخٕص یُس بادشاہس تشریح کرِ۔ {میہ چُھ...: چالڈی، یُس مے لوٚبمُت} {قیدی...: چالدی، یہوداہ کِس قیدٕکۍ بچہٕ}\n26.\\tبادشاہن دیُت جواب تہٕ وونُن دانیالس یُس ناو بلتیشزار اوس، کیا ژے چھکھ میہ سُہ خواب، یُس میہ وُچھمُت چھُ، تہٕ تٔمِچ تعبیر کٔرِتھ ہیکو؟\n27.\\tدانیالن دیُت بادشاہ سٕنزِ موجودگی منز جواب تہٕ وونُن، یُس راز بادشاہن منگمُت چُھ، سُہ ہیکہِ نہٕ بادشاہس نِش ہٲوِتھ۔\n28.\\tمگر آسمانس مَنٛز چُھ اکھ خدا یُس راز ظٲہر کران چُھ، تہٕ بادشاہ نبوکدنضرس یہ زانان چُھ زِ ٲخری دۅہن منز کیا آسہِ۔ چانہِ خواب، تہٕ چانہِ بسترس پیٹھ کلُک وژن، چھِ یِم؛ {maketh...: Chaldee, has made known}\n29. اے بادشاہ، تۅہہِ ہٕندِس ذہنس منز آو تۅہہِ ہٕندِس بسترس پیٹھ، یُس یُس راز ظٲہر کران چُھ، سُہ چُھہ ژیہ زانان زِ کیا سپدِ۔ {آو: کلدی، آو وۅتھ}\n30.\\tمگر یوٚت تام میانہِ خاطرہ چھہ نہ یہ راز میہ برونہہ کنہِ ظٲہر سپدان زِ میہ چھہ کُنہِ تہِ زندٕ کھوتہ زیادہ، بلکہ چھہ تمن ہندِ خاطرہ یُس بادشاہس تشریح زانہِ، تہ ژیہ گژھہِ پننہِ دِلکۍ خیالات۔ {مگر امہ خاطرہ...: یا، مگر امہ ارادہ خاطرہ زِ تشریح ییہ بادشاہس آگاہ کرنہٕ}\n31.\\tاے بادشاہ، وُچھکھ اکھ بٔڈ تصویر۔ یہِ بٔڈ تصویر، ییٚمۍ سٕنٛز چمک {بہت} ٲس، ٲس تۄہہِ برٛونٛہہ کنہِ کھڑا۔ تہٕ امچ شکل ٲس خوفناک۔ {ساویسٹ: چالڈی، وُچھِ}\n32.\\tاَمہِ تصویرُک کلہٕ اوس سۅنہٕ سُند، تٔمۍ سُند سین تہٕ نٔر رۄپہٕ، تٔمۍ سٕنز یٔڈ تہٕ تٔمۍ سٕنزٕ ران، {ران: یا، طرف}\n33.\\tتٔمۍ سٕنزِ زنگہٕ ششتٕرٕچ زنگہٕ، کھۅر ششتٕرُک تہٕ میژِ ہُند حصہٕ۔\n34.\\tژے وُچھ توٚت تام زِ اَتھٕ ورٲے آو اکھ کٔنہِ ژٹنہٕ، یُس تٔمۍ سٕندِس قدمن پیٹھ ششتٕر تہٕ میژِ ہٕنز تصویر لٔگِتھ تہٕ یِمن ٹُکرٕ ٹُکرٕ کٔرِتھ۔ {بغیر...: یا، یُس نہٕ اتھس منز اوس}\n35.\\tاَمہ پتہٕ اوس ششتٕر، میژِ، پیتل، رۄپھ تہٕ سۄنہٕ، یُس یکوٹہ ٹُکرٕ ٹُکرٕ کٔرِتھ تہٕ بنیوو ریتہٕ کالہٕ کِس کھورِ ہٕندۍ پٲٹھۍ۔ تہٕ واو نِتھ تِمن نِش تہٕ تِمن خٲطرٕ لوٚب نہٕ کانہہ جاے: تہٕ سُہ کٔنہِ یُس بُتِہ لوٚگ، سُہ بنیوو اکھ بوٚڈ پہاڑ، تہٕ بٔرِتھ سٲرۍسٕے زمین۔\n36. یہ {چُھ} خواب۔ تہٕ أسۍ ونو بادشاہس برونہہ کُن امچ تشریح۔\n37. اے بادشاہ، ژے بادشاہن ہُند بادشاہ چُھہ، تکیازِ اسمانُک خدایہ چُھ ژے اکھ بادشاہی، طاقت، طاقت تہٕ جلال دِژمُت۔\n38. تہٕ ییتہِ تہِ انسانہٕ سٕندِ اولادٕ روزان چھِ، میدانٕکۍ جانور تہٕ اسمانٕکۍ جاناوار چُھکھ تۅہہِ ہٕندِس اتھس مَنٛز دِژمُت، تہٕ بنووُن تِمن سارِنٕے پى۪ٹھ۔ ژے چھکھ یہ سۅنہٕ سُند کلہٕ۔\n39. تہٕ تۅہہِ پَتہٕ گژھہِ بیاکھ سلطنت پٲدٕ یُس تۅہہِ کھوتہ کمتر آسہِ، تہٕ بیاکھ تریم سلطنت یُس سارِنٕے زمینس پیٹھ راج کرِ۔\n40. تہٕ ژوٗرِم بادشٲہی آسہِ ششتٕرٕکۍ پٲٹھۍ مضبوط: یوتاہ ششتٕر پھُٹراوِ تہٕ سارِنٕے چیزن زیر کرِ۔\n41.\\tتہٕ یێلہِ ژے کھۅر تہٕ کھورِ ہٕندِس میژِ ہُند حصہٕ تہٕ ششتٕرُک حصہٕ وُچھِو، بادشٲہی گژھہِ بٲگراونہٕ۔ مگر اتھ منز آسہِ ششتٕرٕچ طاقت، یوت تام ژے ششتٕر میژِ سٍتۍ رٔلِتھ وُچھِو۔\n42.\\tتہٕ یِتھٕ کٔنۍ زَن کھۄرَن ہٕندِ کھۄر آسہٕ ششتٕرُک تہٕ میژِ ہُند حصہٕ، تہٕ کُنہِ حدس تام آسہِ سلطنت کُنہِ حدس تام مضبوٗط تہٕ کُنہِ حدس تام پھُٹمٕژ۔ {پھُٹمُت: یا، برٹل}\n43.\\tتہٕ یێلہِ ژے ششتٕر رٔلِتھ میژِ سٍتـ̡ رَلاونہٕ آمُت، تِم گژھن نہٕ اَکھ أکِس سٍتـ̡ رَلاونہٕ، یِتھٕ پٲٹھـ̡ ششتٕر میژِ سٍتـ̡ رَلاونہٕ آمُت چُھ۔ {اکھ...: چالڈی، یہِ یتھ سۭتۍ}\n44. تہٕ یِمن بادشاہن ہٕندِس دۅہس مَنٛز کرِ اسمانُک خدایہ اکھ بادشاہت قٲیم، یۄس نہٕ زانہہ تباہ گژھِ، تہٕ بادشاہت گژھہِ نہٕ بییِس لُکن پیٹھ تراونہٕ، {مگر} یہ گژھہِ ٹُکرٕ ٹُکرٕ تہٕ یِمن سارِنٕے بادشٲہی کھٲلِتھ تہٕ یہِ روزِ ہمیشہٕ خٲطرٕ۔ {دۅہہ: چالدی، تہند دۅہ} {بادشٲہی: چالدی، تٔمِچ بادشٲہی}\n45.\\tیوت تام ژیہ وُچھمُت زِ یہ کنہِ اوس بالہٕ منزٕ اتھہٕ ورٲے ژٹنہٕ آمُت، تہٕ یہ چھُ ششتٕر، پیتل، میژِ، رۄپھ تہٕ سۄنہٕ ٹُکرٕ ٹُکرٕ کٔرِتھ۔ عظیم خداین چُھ بادشاہس آگاہ کوٚرمت یُس پتہٕ سپدِ: تہٕ خوابُک {چُھ} یقینی تہٕ امچ تعبیر چُھ یقینی۔ {بغیر...: یا، یُس نہٕ اتھس منز اوس} {امہٕ پتہٕ: چالڈی، امہٕ پتہٕ}\n46. پتہٕ پیوٚو بادشاہ نبوکدنضر تٔمِس بُتھِس پیٹھ، تہٕ کٔرٕن دانیال سٕنز پوجا تہٕ حکم دِتُن زِ تِم گژھن أمِس نذر تہٕ مٔدٕر خوشبو پیش کرنہٕ۔\n47.\\tبادشاہن دیُت دانیالس جواب تہٕ وونُن زِ تُہند خدا چُھ دیوتاہن ہُند خدا، تہٕ بادشاہن ہُند خدا، تہٕ رازن ہُند ظٲہر کرن وول چُھ، یُس ژے یہ راز ظٲہر کٔرِتھ۔\n48. پتہٕ بنوو بادشاہن دانیال اکھ بٔڈ شخص، تہٕ دِتُن أمِس واریاہ بٔڈ تحفہٕ، تہٕ بنووُن سُہ بابل کِس پوٗرٕ صوبس پیٹھ حُکُمران تہٕ بابل کین سارنٕے دانشمندن ہُند سردار۔\n49.\\tتێلہِ کٔر دانیال بادشاہس نِش درخواست تہٕ تٔمۍ تھووُن شدرخ، میشاچ تہٕ عابدنیگو، صوبہٕ بابل کِس معاملس پیٹھ، مگر دانیال اوس بادشاہ سٕندِس دروازس مَنٛز۔","1. نبوکدنضر بادشاہن بنوو سۄنہٕ سُند اکھ مجسمہٕ، ییٚمیُک تھزر {ترےٚہ کیوبِٹ} اوس، {تہٕ} کھجر اوس شےٚ کیوبِٹ: تٔمۍ بنٲو یہِ صوبہٕ بابل کِس میدانس مَنٛز دورہ کِس مٲدانس مَنٛز۔\n2. پتہٕ سوٗز نبوکدنضرن بادشاہن شہزادن، گورنرن تہٕ کپتان، جج، خزانہٕ، مشیر، شیرف تہٕ صوبن ہٕندِس سارنٕے حکمرانن جمع کرنہٕ خٲطرٕ، یُس بادشاہن نبوکدنضرن لگٲومُت اوس۔\n3. پتہٕ گٔیہِ شہزادٕ، گورنرن تہٕ کپتان، جج، خزانہٕ، مُشیر، شیرف تہٕ صوبن ہٕندِ سٲری حکمران، یُس بادشاہن نبوکدنضرن قٲیم کورمُت اوس، تتھ تصویر وقف کرنہٕ خٲطرٕ جمع کرنہٕ۔ تہٕ تِم کھڑا تتھ تصویرس برونہہ کُن یُس نبوکدنضرن ٲس قٲیم کٔرمٕژ۔\n4.\\tاَمہِ پَتہٕ دِژ أکِس بَڑِ پٲٹھۍ، اے لوکو، قومن تہٕ زبانن ہُند حُکُم دِنہٕ آمُت، {بَڑِ پٲٹھۍ: چالدی، طاقتہٕ سٍتۍ} {یہ...: چالدی، تِم چھِ حُکُم}\n5.\\t{یہ} ییلہ تہِ ژیہ کارنیٹ، بانسرۍ، ہارپ، ساکبٹ، زبور، ڈلسیمر تہ پریتھ قسمہ چہ موسیقی ہنز آواز بوزان چھِ، تم چھہِ پیوٚو تہ سۅنہری شکلہِ ہنز پوجا کران یُس نیبوکدنضرن بادشاہن ترتیب دِژمُت چھُ: {ڈلسیمر: یا، گیون: چالڈی، سمفنی}\n6. تہٕ یُس نہٕ پیوٚو تہٕ پوٗزا کرِ، سُہ گژھہِ أتھۍ ساعتس منز دزنہٕ وٲلِس آتش بھٹس مَنٛز تراونہٕ۔\n7. تَمہِ وِزِ ییٚلہِ سارِوٕے لُکو کارنیٹ، بانسری، ہارپ، بُٹہٕ، زبور تہٕ پرٮ۪تھ قٕسمٕچ موسیٖقی ہٕنز آواز بوز، سارِنٕے لوُکھ، قومن تہٕ زبانہٕ گٔیہِ پیوٚو سۅنہٕ سٕندِس مجسمس پوٗزا یُس نبوکدنضرن بادشاہن قٲیم کورمُت اوس۔\n8.\\tامہِ وِزِ آیہِ کینہہ کلدانی نزدیک تہٕ کوٚرُکھ یہودین پیٹھ الزام لگاونہٕ۔\n9. تِمو کٔر کتھ تہٕ وونُن بادشاہ نبوکدنضر، اے بادشاہ، ہمیشہٕ زندٕ۔\n10. اے بادشاہ، ژے چُھ اکھ حکم دِژمُت زِ پرٮ۪تھ کانہہ انسان یُس کارنیٹ، بانسرۍ، ہارپ، بُٹ، زبور تہٕ ڈلسیمر تہٕ پرٮ۪تھ قٕسمٕچ موسیقی ہٕنز آواز بوزِ، سُہ گژھہِ پیوٚو تہٕ سۅنہٕ سٕنزِ شکلہِ ہٕنز پوجا کرِ: {ڈلسیمر: یا، گٮ۪وُن: چالڈی، سمفنی}\n11. تہٕ یُس نہٕ پیوٚو تہٕ پِرِتھ پوجا کرِ، سُہ گژھہِ دزنہٕ وٲلِس آتش بھٹس مَنٛز تراونہٕ یُن۔\n12.\\tکینہہ یہودی چھہِ یِم ژے صوبہٕ بابل، شادرخ، میشاچ تہٕ عابدنیگو کِس معاملس پیٹھ مقرر کٔرۍمٕتۍ۔ اے بادشاہ، یِمو نفرو چُھ نہٕ تۅہہِ سٍتۍ غور کٔرِتھ: تِم چھِنہٕ تُہٕندٮ۪ن دیوتاہن ہٕنز عبادت کران، تہٕ نہ چھِو تٔمِس سۅنہٕ سٕندِس مجسمس پوٗزا کران یُس ژے قٲیم کٔرِمُت چھُ۔ {ہوا...: چالڈی، چُھکھ نہٕ ژے کانہہ خیال تھوومُت}\n13.\\tاَمہِ پَتہٕ دِیُت نبوکدنضرن پننِس غصس تہٕ غصس سٍتـ̡ حُکُم۔ پتہٕ أنۍ تِم نفر بادشاہس برونہہ کُن۔\n14.\\tنبوکدنضرن کٔر کتھ تہٕ تِمن وونُن، اے شدرچ، میشاچ تہٕ عابدنیگو، کیا تُہۍ چھِو نہٕ میانین دیوتاہن ہٕنز عبادت کران، تہٕ نہ چھِو سۅنہٕ سٕنزِ شکلہِ ہٕنز پوجا کران یُس میہ قٲیم کورمُت چھُ؟ {صحیح: یا، مقصدُک}\n15.\\tوۅنۍ اگر توہہِ تیار روزِو زِ کمہِ وِزِ کٔرِو کارنیٹ، بانسرۍ، ہارپ، بُٹ، زبور تہٕ ڈلسیمر تہٕ پرٮ۪تھ قٕسمٕچ موسیٖقی ہٕنز آواز، تہٕ تُہۍ پٔرِو پٔسِتھ پٔرِتھ یُس میہ بنوومُت چھُ۔ {خیر}: مگر اگر نہٕ تم عبادت کرو تیلہِ یِیہٕ تم امی ساعتہ دزنہٕ آتش بھٹس منز تراونہٕ۔ تہٕ سُہ خدا کُس چُھ یُس ژے میانہِ اتھہٕ نِش نجات دِیہِ؟ {ڈلسیمر: یا، گیون: چالڈی، سمفنی}\n16.\\tشادرخ، میشاچ تہٕ عابدنیگوہن دِژ جواب تہٕ وونُن بادشاہس اے نبوکدنضر، أسۍ چھِنہٕ اتھ معاملس منز تۅہہِ جواب دِنہٕ خٲطرٕ احتیاط تھاوان۔\n17.\\tیێلہِ یێلہِ سُہ خدا یُس أسـ̡ عبادت کران چُھ، سُہ چُھہ اسہِ دزنہٕ وٲلِس نارس نِش نجات دِنس قٲبل، تہٕ سُہ کرِ اسہِ تُہندِ اتھہٕ نِش نجات دِنہٕ، اے بادشاہ۔\n18. مگر اگر نہ، اے بادشاہ، ژے گژھہِ یہ زان زِ أسۍ کرو نہٕ تہندٮ۪ن خداہن ہٕنز خدمت، تہٕ نہ کرو سۅنہٕ سنہٕ بُتٕچ پوجا یُس ژے قٲیم کورمُت چھُ۔\n19.\\tاَمہِ پَتہٕ اوس نبوکدنضر غصہٕ سٍتـ̡ بٔرِتھ تہٕ تٔمۍ سٕندِس شکلہِ ہٕنز شکل بدلٲوٕنـ̡ شَدرچ، میشاچ تہٕ عابدنیگوہس خٕلاف: {لہذا} دِژ تٔمۍ کٔر کتھ تہٕ حُکُم زِ تِم گژھن بھٹہٕ گرم کرنہٕ کھۅتہٕ سَتھ گنہٕ زیادٕ گرم کرنہٕ۔ {مکمل: چالڈی، بٔرتھ}\n20. تہٕ تٔمۍ دِیُت سارِوٕے کھۄتہٕ طاقتور نفرن یُس أمۍ سٕندِس لشکرس منز ٲس، تِم کٔرِن شادراچ، میشاچ تہٕ عابدنیگو رٔٹِتھ تہٕ دزنہٕ وٲلِس آتش بھٹس منز تراوُن۔ {زیادٕ...: چالڈی، طاقتُک طاقت}\n21. پتہٕ آیہ یِم نفر پننین کوٹن، ہوسین، ٹوپۍ، تہٕ باقٕے پلون منٛز بٔنِتھ تہٕ دزنہٕ نارس منز تراونہٕ۔ {کوٹس: یا، مینٹلز} {ٹوپۍ: یا، پگڑی}\n22.\\tتِکیازِ بادشاہ سُند حُکُم اوس عجل، تہٕ بھٹہ اوس واریاہ زیادٕ گرم، نارٕکہِ نارن مارۍ تِم نفر یِمو شادراچ، میشاچ تہٕ عابدنیگو رٔٹۍ۔ {حکم: چالدی، لفظ} {شعلہ: یا، چنگاری}\n23.\\tتہٕ یِم تریہ نفر شادراک، میشاچ تہٕ عابدنیگو پیوٚو دزنہٕ وٲلِس آتش کِس بھٹس منز بند۔\n24. اَمہِ پتہٕ گوٚو نبوکدنضر بادشاہ حٲران تہٕ ووٚتھ جلدی تہٕ ووٚنُن پننین مشیرن زِ کیا أسۍ ترےٚ نفر نارس مَنٛز بٔنِتھ ترٛٲوِتھ؟ تِمو دِژ جواب تہٕ وونُن بادشاہس پوٚز اے بادشاہ۔ {کونسلر: یا، گورنرز}\n25.\\tتٔمۍ دیُت جواب تہٕ وونُن، لو، بہٕ چُھس وُچھان ژور نفر نارس منز پکان تہٕ تِمن چُھنہٕ کانہہ دگ لگان۔ تہٕ ژورمہِ ہنز شکل چھیہ خدایہ سٕندِ فرزند سٕندِ پٲٹھۍ۔ {تِم...: چالڈی، تمن منز چھُنہٕ کانہہ تکلیف دِنہٕ}\n26. اَمہِ پَتہٕ ووت نبوکدنضر دزنہٕ وٲلِس آتش کِس بٹھس نِش، {تہٕ} ووٚنُن تہٕ وونُن، شادراک، میشاک تہٕ عابدنیگو، اے اعلیٰ خدایہ سٕندِ خادم، یِمو نیبر تہٕ یِنہٕ یِنہٕ۔ پتہٕ دراو شادراک، میشاچ تہٕ عابدنیگو، نارس منزہ نیبر۔ {ٲس: چالڈی، دروازٕ}\n27.\\tتہٕ شہزادن، گورنرن تہٕ کپتانن تہٕ بادشاہ سٕندِس مُشیرو یکوٹہ جمع سپدِتھ وُچھ یِم نفر، یِمن ہٕندِس جسمس پیٹھ اوس نہٕ نارُک کانہہ طاقت تہٕ نہ اوس تِمن ہٕندِس کلہٕ سُند اکھ مس تہٕ نہ اوس تِمن ہٕندِس کوٹ بدلاونہٕ آمُت، تہٕ نہ اوس تِمن پیٹھ نارٕچ خوشبو ژٔلِتھ۔\n28. {پتہٕ} نبوکدنضرن کٔر کتھ تہٕ وونُن، شادراک، میشاچ تہٕ عابدنیگو ہٕندِس خداہس سٍتـ̡ مبارک ہو، یٔمۍ پَنُن فرشتہٕ سوٗزمُت تہٕ تٔمِس پَنٕنـ̡ پَنٕنـ̡ خدایہِ سٍتـ̡ نجات دِژمٕژ تہٕ بادشاہ سُند کلام بدلووُکھ تہٕ تِمن ہٕندِس لاشہٕ دِژمٕتـ̡ یُس نہٕ پننِس خداہس علاوٕ کُنہِ تہِ خدایہِ سٕنز عبادت کٔرِتھ تہٕ کٔرِن نہٕ کُنہِ خداہٕچ عبادت کٔرِتھ۔\n29.\\tتێلہِ چُھس بہٕ اَکھ فرمان دِوان زِ پرٮ۪تھ کانہہ لوک، قوم تہٕ زبان، یُس شادراک، میشاچ تہٕ عابدنیگو کِس خدایس خلاف کانہہ غلط کتھ کران آسہِ، یِن ٹُکرٕ ٹُکرٕ کرنہٕ یِن، تہٕ تِہٕندِس مکانس یِن گُرِ بناونہٕ: کیازِ کانہہ تہِ چُھہ نہٕ کانہہ تہِ خدا یُس امہِ قسمہٕ پتہٕ نجات دِتھ۔ {بہٕ چُھس کران...: چالڈی، اکھ فرمان چُھ میہ دِنہٕ آمُت} {کانٛہہ تہِ...: چالڈی، غلطی} {کٹ ...: چالڈی، بٔنِتھ ٹُکرٕ}\n30.\\tپتہٕ دِژ بادشاہن صوبہٕ بابل کِس صوبس مَنٛز شادرخ، میشاچ تہٕ عابدنیگو ترقی دِنہٕ۔ {ترقی دِنہٕ: چالڈی، ترقی خٲطرٕ بناونہٕ}","1. نبوکدنضر بادشاہ، سارنٕے لُکن، قومن تہٕ زبانن خٲطرٕ، یُس سارِنٕے زمینس مَنٛز روزان چھُ۔ تۅہہِ گژھہِ تسلی دِنۍ۔\n2. میہ باسیوو اصل زِ خداین دِژ میہ سٍتـ̡ یِم نشانہٕ تہٕ عجائب ہاونہٕ یِن۔ {میہ سونچ...: چالڈی، یہ اوس میہ برونہہ کنہِ}\n3. تٔمۍ سٕنزِ نشانہٕ کوتاہ عظیم چھِ! تہٕ تٔمۍ سٕندۍ عجائبات کوتاہ طاقتور چھِ! تٔمۍ سٕنٛز بادشاہی {چِھ} اکھ ابدی بادشاہی، تہٕ تٔمۍ سٕنٛز سلطنت {چِھ} نسل در نسل۔\n4. بہٕ اوس نبوکدنضر پننِس مکانس مَنٛز آرام کٔرِتھ، تہٕ میٲنِس محلس مَنٛز پھۄلان۔\n5.\\tمیہ وُچھ اکھ خواب ییمہ سٍتۍ میہ خوفزدہ گوو، تہٕ میٲنس بسترس پیٹھ موجود خیالات تہٕ میٲنس کلہٕ کین وژنن کٔر میہ پریشان۔\n6. تێمہِ کِنۍ دیت میہ یہ حکم زِ سُہ کرِ بابل کین سارنٕے دانا پانس برونہہ کُن، یُتھ زن تِم میانہِ برونہہ کنہِ خوابٕچ تعبیر کرِ۔\n7. اَمہ پتہٕ آو جادوگرن، نجومی، کلدانی تہٕ کُچھن وٲلۍ: تہٕ مے وون تِمن برونہہ کُن خواب۔ مگر تمو کٔر نہ میہ امچ تشریح زان۔\n8.\\tمگر ٲخرس پیٹھ آو دانیال میانہِ برونہہ کنہِ، یمۍ سُند ناو {اوس} بلتیشزار اوس، میانہِ خدایہ سٕندِ ناوٕ مطٲبق، تہٕ یٔمِس مَنٛز {چُھ} مقدس دیوتاہن ہُند روح اوس، تہٕ أمِس برونہہ کُن وون میہ خواب، {ونن}،\n9.\\tاے بلتیشزار، جادوگرن ہُند مالک، کیازِ بہٕ چھُس پتاہ زِ مقدس دیوتاہن ہُند روح چُھہ ژے منز، تہٕ کانہہ راز چھُنہٕ ژے پریشان کران، مے وَن میانین خوابن ہُند وژن یُس مے وُچھمُت چھُ، تہٕ تٔمِچ تعبیر کٔرِتھ۔\n10.\\tیتھہ پاٹھۍ ٲسۍ میٲنس بسترس منز میانۍ کلہ وژن؛ میہ وچھ زمینس منز اکھ کُل، تہ امیک تھزر اوس واریاہ بوٚڈ۔ {میہ وُچھمُت: چالڈی، میہ اوس وُچھان}\n11.\\tکُل بوٚڈ تہٕ مضبوط، تہٕ اَمیُک تھزر ووت آسمانس تام، تہٕ ووت سارِنٕے زمینہٕ کِس اندس تام:\n12.\\tاَمہِ ہٕندِ پنہٕ ؤتھٕر ٲسۍ گورٕ تہٕ اَتھ مَنٛز اوس سارِنٕے خٲطرٕ ماز تہٕ اَتھ مَنٛز اوس سارِنٕے خٲطرٕ ماز آسان: کھہٕکۍ جانور ٲسۍ اَتھ تَل ژھایہِ تہٕ اسمانٕکۍ جاناوار ٲسۍ اَمہ کِس لٔنڈِس مَنٛز روزان، تہٕ سارِوٕے ماز اوس اَمہ سٍتـ̡ کھٮ۪نہٕ آمُت۔\n13.\\tمیہ وُچھ پننِس بسترس پیٹھ پننِس کلہٕ سٕندِس وژنس منز، تہٕ وُچھ اکھ وُچھن وول تہٕ اکھ پاک وُچھن آسمانہٕ پیٹھ۔\n14.\\tتٔمۍ کٔر بَڑِ کُلِس ژٹِتھ تہٕ تٔمۍ سٕنزِ لنجہِ ژٔٹِتھ ژٔٹِتھ تہٕ پنہٕ وُن پھلہٕ پھٔٹِتھ پھٔہلِتھ تہٕ جاناوار ژٔلِن اَتھ تلہ کنہِ، تہٕ جاناوار ژٔلِن تٔمۍ سٕنزِ لنجہِ منز: {بَڑِ پٲٹھۍ: چالدی، طاقتہٕ سٍتۍ}\n15.\\tتوتہِ ترٲوِن پننہِ موٗل ہُند ٹھنڈ زمینہِ منز، شیشتٕرِ تہٕ پیتلُک پٔنڈ تہِ، کھہٕ کِس نرم گاسہٕ منز۔ تہٕ یہ گژھہِ اسمانہ کِس شبنم سٍتۍ اودُر، تہٕ تٔمۍ سُند حصہٕ گژھہِ زمینہِ ہٕندِس گاسہٕ سٍتـ̡ درندن سٍتـ̡ آسُن:\n16. تٔمۍ سُند دِل گژھہِ انسان سٕندِ نِش بدلاونہٕ یُن، تہٕ أکِس درندٕ سُند دِل گژھہِ أمِس دِنہٕ۔ تہٕ سَتھ لٹہِ گٔژھِن أمِس پیٹھ۔\n17.\\tیہ معاملہٕ چُھ نگرن ہٕندِس حکمس سٍتـ̡ تہٕ مُقدسن ہٕندِس کلامَس سٍتـ̡ تقاضہٕ کرنہٕ آمُت: یێلہِ زِ زندٕ روزِ زِ اعلیٰ ترین چُھ انسانن ہٕندِس بادشاہتس مَنٛز حکمرٲنی کران، تہٕ یێمِس یُس یژھہٕ دِوان چُھ، تہٕ یێمِس سٍتـ̡ دِوان چُھ، تہٕ اَتھ پیٹھ دِیہِ اَتھ پیٹھ بدترین انسان۔\n18.\\tیہ خواب، میہ بادشاہ نبوکدنضرن وُچھمُت۔ وۅنۍ چُھہ ژے اَمہ چہ تشریح ہُند اعلان کٔرِتھ، یێلہِ میانہِ بادشٲہی ہٕندِ سارِنٕے دانا چھِنہٕ میانہِ تشریح زانِتھ: مگر ژے چھُکھ قٲبل۔ تِکیازِ مقدس خداہٕ سُند روح چُھ توے مَنٛز۔\n19.\\tتمہ پتہ گۆو دانیال، یمۍ سُند ناو {اوس} بلتیشزار اوس، اکس گھنٹس تام حیران گوو، تہ تسند خیال گۆو تس پریشان۔ بادشاہن کٔر کتھ تہٕ وونُن، بلتیشزار، خواب، یا امچ تعبیر گژھ نہٕ ژے پریشان۔ بلتیشزارن دیُت جواب تہٕ وونُن، میانہِ آقا، تِمن خٲطرٕ گژھ خواب، تہٕ تُہند تعبیر تہٕ تُہند تشریح تہٕ تُہند دُشمن خٲطرٕ۔\n20. سُہ کُل یُس ژے وُچھمُت، یُس وُچھمُت اوس تہٕ مضبوط اوس، یُس آسمانس تام ووت تہٕ سٲرۍسٕے زمینس تام ووت تہٕ سُہ وُچھُن سٲرۍسٕے زمینس تام۔\n21.\\tیمۍ سٕندِ پنہٕ ؤتھٕر گورٕ ٲس، تہٕ تِمن ہُند پھل اوس سارِنٕے خٲطرٕ ماز تہٕ اَتھ مَنٛز سارِنٕے خٲطرٕ ماز اوس۔ یتھ تل میدانٕکۍ جانور روزان ٲسۍ، تہٕ یٔمۍ سٕنزِ لنجہِ پیٹھ اسمانٕکۍ جاناوار پنٕنۍ روزن واجنہِ ٲسۍ۔\n22. اے بادشاہ، یہِ چُھہ ژے بٔڈِتھ تہٕ مضبوٗط بنان چُھ، تکیازِ تُہٕنز عظمت چھے بڑیمٕژ، تہٕ چُھہ اسمانس تام وٲتِتھ، تہٕ تُہٕنز سلطنت چھے زمینہٕ کِس اندس تام واتان۔\n23.\\tتہٕ بادشاہن وُچھ اکھ وُچھن وول تہٕ اکھ مقدس یُس آسمانہٕ پیٹھٕ وسان چھُ، تہٕ وَنُن زِ کُلِس ژٔٹِتھ تہٕ تباہ کٔرِو۔ توتہِ تراوُن زمینہِ منز ششتٕر تہٕ پیتلُک اکھ ٹُکرِ ہیتھ تہِ، کھہٕ کِس نرم گاسہٕ منز۔ تہٕ یہ گژھہِ اسمانہ کِس شبنم سٍتۍ اودُر، تہٕ تٔمۍ سُند حصہٕ گژھہِ کھہٕ کین درندن سٍتۍ، یوٚت تام سَتھ لٹہِ أمِس پیٹھ۔\n24.\\tیہ {چُھ} تشریح، اے بادشاہ، تہٕ یہ {چُھ} اعلیٰ سُند حکم، یُس میٲنس آقا بادشاہس پیٹھ آمُت چُھ:\n25.\\tیُس تِم ژےٚ انسانو نِش ژٔلِتھ ژٔلِتھ تہٕ تُہُند روزُن روزن مٲدانن ہٕندِس درندَس سٍتۍ، تہٕ تِم کرِ ژےٚ گاسہٕ کھٮ۪نہٕ خٲطرٕ، تہٕ تِم کرِ اسمانٕچ شبنم سٍتـ̡ تہٕ سَتھ لٹہِ ژے پٲٹھۍ، یوتام ژے پتاہ گژھہِ زِ انسانن ہٕندِس بادشاہتس مَنٛز چھُ سارِوٕے کھۄتہٕ اعلیٰ حُکوٗمت۔  تہٕ یُس تہِ یژھان دِوان چھُ۔\n26. تہٕ ییلہ تمو کُلِچ موٗل تراونُک حکم دِیُت۔ تۅہہِ آسہِ تۅہہِ پٲٹھۍ، تمہ پتہ گژھہِ ژیہ پتاہ زِ آسمانن ہنز حکمرٲنی چھیہ کران۔\n27. اَمہِ مۄکھٕ اے بادشاہ، میٲنۍ مشورٕ گژھہِ ژے خٲطرٕ قبول، تہٕ نیکی سٍتـ̡ کٔرٕن پنٕنۍ گۅناہ تہٕ غریبن پیٹھ رحم کٔرِتھ پنٕنۍ گۅناہ تہٕ پنٕنۍ گناہ ختم کرنہٕ۔ اگر یہ چانہِ سکون ہُند زیچھر آسہِ۔ {اکھ زیٹھراوُن...: یا، پننہِ غلطی ہند شفا}\n28.\\tیہ سورُے آو بادشاہ نبوکدنضرس پیٹھ۔\n29. بہن ریتن پتہٕ پوٚک سُہ بابل کِس بادشاہت کِس محلس مَنٛز۔ {منز: یا، upon}\n30. بادشاہن ووٚن تہٕ وونُن، کیا یہِ عظیم بابل چھُنہٕ یُس میہ پننہِ طاقتہٕ کہِ طاقتہٕ سٍتـ̡ بادشاہت کِس گرٕ خٲطرٕ تہٕ پننہِ عظمتٕچ عزتہٕ خٲطرٕ بنوومُت چُھ؟\n31.\\tییلہ بادشاہ سٕندِس ٲسس منز لفظ {اوس}، آسمانہٕ پیٹھہٕ دراو اکھ آواز، {ونان}، اے بادشاہ نبوکدنضر، ژے چُھہ یہِ بولنہٕ آمُت۔ بادشٲہی چُھ ژے نِش ژٔٹمٕژ۔\n32. تہٕ تِم کٔرِن تۅہہِ انسانو نِش ژٔلِتھ تہٕ تُہُند روزن گاسہٕ کھٮ۪نہٕ خٲطرٕ، تہٕ سَتھ لٹہِ گژھن توے پیٹھ، یوتام نہٕ ژیہ پتاہ گژھہِ زِ سارِوٕے کھۄتہٕ اعلیٰ چُھ انسانن ہٕندِس بادشٲہی مَنٛز حُکوٗمت کران، تہٕ یُس یُس یژھہٕ دِوان چُھ۔\n33.\\tیۅہے ساعتہ سپُد نبوکدنضرس سٍتـ̡ پورٕ: تہٕ سُہ آو انسانو نِش کڈنہٕ، تہٕ گاسہٕ کھیوٚن گاسہٕ، تہٕ تٔمۍ سُند جسم اوس اسمانہٕ کِس شبنم سٍتـ̡ اودُر، یوتام تٔمۍ سٕندِس مَس گٔیہِ عقاب ہٕندِس پٲٹھۍ، تہٕ تٔمۍ سٕندِ کیل گٔیہِ جاناوارن ہٕندِ پٲٹھۍ۔\n34. تہٕ دۅہہٕ کِس ٲخرس پیٹھ تُل میہ نبوکدنضرن پنٕنۍ أچھ آسمانس کُن، تہٕ میٲنۍ سمجھ آو میہ کُن واپس، تہٕ مے کٔر تٔمِس سٕنز تعریف تہٕ عزت یُس ہمیشہ زندٕ روزان چُھ، یٔمۍ سٕنز سلطنت چھِ ابدی سلطنت تہٕ تٔمۍ سٕنز بادشاہی چھے نسل در نسل۔\n35.\\tتہٕ زمینٕکۍ سارِنٕے بسکیٖن دِنہٕ آمٕتۍ چھِ، تہٕ سُہ چُھ پننہِ مرضی مُطٲبق آسمانہٕ کِس لشکرس مَنٛز، تہٕ زمینہٕ کین بسکینن مَنٛز چُھہ تہٕ کانہہ تہِ ہیکہِ نہٕ أمِس اتھہٕ رُکٲوِتھ، تہٕ تُہۍ کیا چُھکھ کٔرِتھ؟\n36.\\tامی ساعتہ آو میون عقل میہ نش واپس۔ تہٕ میانہِ بادشٲہی ہٕندِ عظمتٕچ شان خٲطرٕ، میٲنۍ عزت تہٕ چمک آو مےٚ واپس۔ تہٕ میٛٲنۍ مُشیر تہٕ میٲنۍ مالہٕ کٔر مےٚ یژھان۔ تہٕ بہٕ اوسُس پننہِ سلطنتس مَنٛز قایم سپُدمُت، تہٕ بہٕ گٔیہٕ بہٕ سٍتـ̡ عظیٖم شُمار شٲمِل کرنہٕ۔\n37. وۅنۍ چُھس بہٕ نبوکدنضر اسمانٕکۍ بادشاہ سٕنز تعریف تہٕ تعریف، تہٕ تٔمۍ سٕندِس طریقس سٍتـ̡ تہٕ یِمن ہٕندِس کامہِ سٍتـ̡ سٍتـ�","1.\\tبیلشزار بادشاہن کٔر پننین ساسن مالکن خٲطرٕ اکھ بٔڈ دعوت تہٕ ساسہٕ بٔڈۍ برٛونٛہہ۔\n2. بیلشزارن ییلہ أمس شرابُک مزہ چکھ، حکم دِیُت سۄنہٕ تہٕ رۄپہٕ ہٕندۍ بانہٕ یُس تٔمۍ سٕندِس مٲلۍ نبوکدنضرن ہیکل منزٕ نِمُت اوس یُس یروشلمس مَنٛز اوس۔ تاکہ بادشاہ تہٕ أمۍ سٕنٛدِ شہزادٕ، أمۍ سٕنٛزٕ زنانہٕ تہٕ تٔمۍ سٕنٛزٕ لونڈین گژھن اَتھ منٛز چیٚنہٕ۔ {مول: یا، بب بب} {نِنہٕ: چالڈی، اننہٕ}\n3. پَتہٕ أنۍ تِمو سۄنہٕ بانہٕ یِم خدایہ سٕندِ گرٕ کِس مندرٕ منزٕ نِنہٕ آمٕتۍ یُس یروشلمس مَنٛز اوس۔ تہٕ بادشاہ تہٕ أمۍ سٕنٛدٮ۪و شہزادٕ، أمۍ سٕنٛزِ زنانہٕ تہٕ تٔمۍ سٕنٛزٕ لونڈیو ٲسۍ یِمن منٛز شراب۔\n4. تِمو کٔر شراب، تہٕ سۄنہٕ تہٕ رۄپہٕ، پیتل، ششتٕر، لٔکرِ تہٕ کنن ہٕندِس دیوتاہن ہٕنز تعریف۔\n5.\\tأتھۍ ساعتہ دراو أکِس شخصہٕ سٕندِ اتھہٕ سٕنزِ اوٚنگجہ تہٕ لیوٚکھُن بادشاہ سٕندِس محلہٕ کِس دیوارس پیٹھ شمعہٕ سٕندِس سٍتـ̡ لیٚکھُن: تہٕ بادشاہن وُچھ اَتھُک سُہ حصہٕ یُس لیکھان اوس۔\n6.\\tپتہٕ آو بادشاہ سُند بُتھ بدلاونہٕ، تہٕ تٔمۍ سٕندِس خیالن گٔیہِ تٔمِس پریشان، یُتھ زن تٔمۍ سٕندِس کمرن ہٕندۍ جوڑ یلہٕ گٔیہ، تہٕ تٔمۍ سٕندٮ۪ن کۅٹھن لٔگۍ اکھ أکِس سٍتۍ۔ {شکلہٕ: چالدی، چمک} {تبدیٖل کَرنہٕ آمُت: چالڈی، بَدلاونہٕ آمُت} {جوڑ: یا، گرڈلز: چالڈی، باینڈنگس، یا، گانٹھ}\n7.\\tبادشاہن کٔر بَڑِ پٲٹھۍنجومی، کلدانی تہٕ کُچھن اننہٕ خٲطرٕ۔ {تہٕ} بادشاہن کٔر کتھ تہٕ وونُن بابل کین دانشمندن زِ یُس تہٕ یُس یہِ تحریر پٔرِتھ تہٕ مے امِچ تشریح ہٲوِ، سُہ گژھہِ سرخ پوش لاگنہٕ یُن، تہٕ سۅنہٕ سٕندِس گردنس منز آسہِ سۄنہٕ سُند زنجیر، تہٕ سُہ آسہِ سلطنتُک تریم حُکُمران۔ {بَڑِ پٲٹھۍ: چالدی، طاقتہٕ سٍت} {سرخ رنگ: یا، جامنی رنگ}\n8.\\tاَمہ پتہٕ آو بادشاہ سٕندِس سارِنٕے دانشمندَن مَنٛز، مگر تِم ہیوٚک نہٕ تحریر پٔرِتھ، تہٕ نہ ہیوٚک بادشاہس امِچ تشریح زانِتھ۔\n9.\\tاَمہِ پتہٕ گوٚو بادشاہ بیلشزار سٮ۪ٹھاہ پریشان، تہٕ تٔمۍ سُند بُتھ گوٚو أمِس مَنٛز تبدیل، تہٕ تٔمۍ سٕندِ آقا گٔیہِ حٲران۔ {شکلہٕ: چالدی، چمک}\n10.\\t{وۅنہِ}ملکہ آیہِ بادشاہ تہٕ تٔمۍ سٕندِس مٲلکَن ہٕندِ کلامَس سٍتۍ ضیافتہٕ خانس منز: {تہٕ} ملکہِ کٔر کتھ تہٕ وونُن، اے بادشاہ، ہمیشہٕ خٲطرٕ زِندٕ: تُہند خیال گژھہِ نہٕ تُہٕندِس بُتھِس مَنٛز دِنہٕ یُن:\n11. تُہنزِ بادشٲہی مَنٛز چُھ اَکھ شخٕص یٔمِس مَنٛز چُھ مقدس خداہَن ہُند روح آسان۔ تہٕ تٔمۍ سٕندِس مٲلہِ سٕندِس زمانس مَنٛز اوس گاش تہٕ فہم تہٕ حکمت، دیوتاہن ہٕنزِ حکمتٕکۍ پٲٹھۍ، أمِس مَنٛز لبنہٕ آمُت۔ یُس بادشاہ نبوکدنضر تُہند مول، بادشاہ، {بہٕ چُھس ونان}، تُہند مٲل، بنیوو جادوگرن، نجومی، کلدین، {تہٕ} کُنترس ہُند مٲلک۔ {مول: یا، بب بب}\n12.\\tیُس اکھ بہترین روح، تہٕ علم، تہٕ فہم ، خوابن ہٕنز تعبیر کرٕن، تہٕ سخت جملن ہُند ظٲہر کرُن، تہٕ شکوک دوٗر کرنہٕ خٲطرٕ آو أتھۍ دانیالس مَنٛز لبنہٕ، یٔمِس بادشاہن بلتیشزار ناو اوس، وۅنۍ گژھہِ دانیال بُلاونہٕ، تہٕ سُہ کرِ تشریح ہاونہٕ۔ {ترجمان: یا، ترجمہٕ کار سٕنز} {تحلیل کرُن: یا، تحلیل کرن والہٕ} {شَک: چالڈی، ناٹس}\n13. پتہٕ آو دانیال بادشاہس برونہہ کُن اننہٕ۔ {تہٕ} بادشاہن ووٚن دانیالس سٍتـ̡ تہٕ وونُن زِ یہوداہ سٕندِس قٲد کِس شُرین ہُند کُس {چُھ} چُھ، یُس میانہِ مٲلہِ یہودی سٍتـ̡ دِنہٕ آمُت چُھ؟ {مول: یا، بب بب}\n14.\\tمیہ چُھہ تۅہہِ مُتلِق تہِ بوزمُت زِ دیوتاہن ہُند روح چُھہ ژے مَنٛز تہٕ گاش تہٕ فہم تہٕ بہترین حکمت چُھہ ژے مَنٛز لبنہٕ یِوان۔\n15.\\tتہٕ وۅنۍ چھِ دانشمند {مرد}، نجومی، میانہِ برونہہ کنہِ اننہٕ آمٕتۍ، زِ تِم گژھن یہ تحریر پٔرِتھ، تہٕ اَمہ ہٕنز تشریح کٔرِن میہ برونہہ کُن، مگر تِم ہیوٚک نہٕ امہِ چیزٕچ تشریح ہٲوِتھ:\n16.\\tتہٕ مے چُھہ تۅہہ بوزمُت زِ ژے ہیکِو تشریح کٔرِتھ، تہٕ شک دوٗر کٔرِتھ، وۅنۍ یێلہِ ژے تحریر پٔرِتھ تہٕ اَمہ ہٕنز تشریح کٔرِتھ تہٕ تێلہِ گژھہِ سرخ پوشہٕ لٲگِتھ، تہٕ پننہِ گردنہِ سٍتـ̡ سۄنہٕ زنجیر لٲگِتھ، تہٕ بنہٕ بادشاہتس مَنٛز تریم حُکُمران۔ {تشریح کٔرِو:Chaldee, interpret, etc}\n17.\\tتێلہِ دِژ دانیالن جواب تہٕ وونُن بادشاہس برونہہ کُن، چانۍ تحفہٕ گژھن پانس خٲطرٕ، تہٕ دِیُن پنُن انعام۔ توتہِ کرٕ بہٕ پادشاہس یہ تحریر پٔرِتھ، تہٕ تٔمِس کٔرٕ تشریح زان۔ {انعام: یا، فیس}\n18.\\tاے بادشاہ، اے اعلیٰ خداین دِژ پننِس مٲلِس نبوکدنضرس اکھ بادشٲہی تہٕ عظمت، عظمت، عظمت تہٕ عزت:\n19.\\tتہٕ یُس عظمتُک تٔمِس دِژمُت اوس، سارِنٕے لوُکھ، قومن تہٕ زبانہٕ گٔیہِ أمِس برونہہ کُن تھرتھر تہٕ خوفہٕ: سُہ کُس مارِ۔ تہٕ کُس سُہ زندٕ تھاوُن۔ تہٕ سُہ کُس قٲیم کرِ۔ تہٕ سُہ کُس تراوِ سُہ دِیہِ۔\n20.\\tمگر ییلہ تٔمۍ سُند دِل تُلِتھ تہٕ تٔمۍ سُند دٮ۪ماغ گٔیہِ فخرٕ سٍتـ̡ سخٕت، سُہ آو پنہٕ نِس بادشاہ تختہٕ پیٹھٕ معزول کرنہٕ، تہٕ تِمو نِش تٔمۍ سُند جلال نِش نِنہٕ: {فخرٕ منز: یا، فخرٕ سان ورتاوُن} {معزول کرنہٕ: چالدی، آو بۄن وسُن}\n21.\\tتہٕ سُہ آو انسانن ہٕندِس نیٚچوِس نِش کڑنہٕ۔ تہٕ تٔمۍ سُند دِل اوس درندن ہٕندۍ پٲٹھۍ، تہٕ تٔمۍ سُند روزن اوس جنگلی گَرَن سٍتۍ: تِمو دِژ أمِس بیلن ہٕندۍ پٲٹھۍ گاسہٕ کھٮ۪وان، تہٕ تٔمۍ سُند جسم اوس آسمانہٕ کِس شبنم سٍتۍ اودُر۔ یوتام تس یہ پتاہ اوس زِ انسان سٕندِس بادشاہتس منز چُھ اعلیٰ ترین خدا حکومت کران، تہٕ {یہ} چُھ سُہ اتھ پیٹھ یُس یژھہٕ مقرر کران چُھ۔ {أمۍ سُنٛد دِل...: یا تٔمۍ بنوو پنُن دِل برابر، وغیرہ}\n22.\\tتہٕ تٔمۍ سٕندِس نیچوِس اے بیلشزار، ژے چُھہ نہٕ پنُن دِل عاجز کورمُت، یێلہِ تہٕ ژے یہ سورُے زانان چھُ۔\n23.\\tمگر پان تُلتھ آسمانہ کِس رب سٍتـ̡ ۔ تہٕ تِمو أنۍ تٔمۍ سٕندِس گرٕکۍ بانہٕ تہٕ تۅہہِ تہٕ تُہٕندِس مٲلکَن، زنانہٕ تہٕ تُہٕنزِ لونڈیو چُھکھ تِمن منز شراب۔ تہٕ ژے کٔر رۄپہٕ تہٕ سۄن، پیتل، ششتٕر، لٔکر تہٕ کنن ہٕندٮ۪ن دیوتاہن ہٕنز تعریف، یِم نہٕ وُچھان چھِ، تہٕ بوزان چھِ، تہٕ سُہ خدایہ یٔمۍ سٕندِس اتھس مَنٛز چُھ، تہٕ یٔمۍ سٕندِس سارِنٕے وَتہٕ چُھ، تہٕ یٔمۍ سٕندِس سارِنٕے وَتہٕ چُھ، تٔمۍ سٕندِس سٍتـ̡ چُھہ نہٕ تُہٕندِس سٍتـ̡ جلال دِنہٕ آمُت:\n24.\\tاَمہِ پَتہٕ اوس أمِس سٕندِ طرفہٕ سوزنہٕ آمُت اَتھُک حصہٕ۔ تہٕ یہ تحریر ٲس لیکھنہٕ آمژ۔\n25.\\tتہِ چھہ سہ تحریر یُس لیکھنہ آمت اوس، مینی، مینی، ٹیکل، اوفرسن۔\n26.\\tیہِ {چھُ} چیزٕچ تشریح: MENE؛ خداین چُھ تُہنزِ بادشٲہی گنزرٲومٕژ تہٕ مُکمل کٔرمٕژ۔\n27. ٹیکل۔ تۅہہ چُھس وزنس منز تول کرنہٕ آمُت، تہٕ چُھس محتاج لبنہٕ آمُت۔\n28. پیرس؛ تُہٕنٛز سلطنت آیہِ تقسیٖم کرنہٕ، تہٕ دِنہٕ آمٕژ میڈین تہٕ فارسِین دِنہٕ۔\n29.\\tاَمہِ پَتہٕ دِیُت بیلشزارُک حُکُم، تہٕ تِمو لوٚگ دانیالس سٕندِس گردنَس سٍتـ̡ سۄنہٕ سُند زنجیر، تہٕ کورُن أمِس مُتعلِق اعلان زِ سُہ گژھہِ سلطنتُک تریم حُکُمران بنہٕ۔\n30.\\tاَمہِ رٲژ اوس بلشزار یُس کلدانن ہُند بادشاہ مارنہٕ آو۔\n31.\\tتہٕ داریوس مدین کٔر بادشاہت، یُس تقریباً تریہ تہٕ زٕ وُہُر اوس۔ {being...: Chaldee، سہ بطور نیچو، وغیرہ} {متعلق: یا، وۄن}","1. داریوس آو خۅش زِ سُہ اوس سلطنتس پیٹھ اکھ ہتھ وُہ شہزادہ مقرر کرُن، یُس پورٕ سلطنتس پیٹھ آسُن۔\n2. تہٕ یمن ترین صدرن پیٹھ؛ یمن منز دانیال گۅڈہ اوس، زِ شہزادن دِن تمن حسابہ، تہ بادشاہس گژھہِ نہ کانہہ نقصان۔\n3.\\tتێلہِ اوس یہ دانیال صدرن تہٕ شہزادن کھوتہ زیادٕ ترجیح دِنہٕ، تکیازِ تس منز اوس اکھ بہترین روح {اوس}۔ تہٕ بادشاہن سونٛچ زِ سُہ کرِ سٲرۍسٕے سلطنتس پیٹھ۔\n4.\\tامہ پتہ کٔر صدرن تہٕ شہزادن بادشاہتس متعلق دانیالس خلاف موقعہ ژھانڈنچ کوشش۔ مگر تِمن ہیوٚک نہٕ کانٛہہ موقعہٕ تہٕ نہ عیب لٔبتھ۔ یوت تام سُہ وفادار اوس، نہ اوس تس منز کانہہ غلطی یا غلطی لبنہٕ۔\n5.\\tتێلہِ وۆن یِمو مردو زِ اسہِ میلہِ نہ اتھ دانیالس خلاف کانہہ موقعہ، یوتام نہ اسہِ تس خلاف تٔمۍ سٕندِس خدایہ سٕندِس قانونس مُتلق میلہِ۔\n6. پَتہٕ گٔیہِ یِم صدر تہٕ شہزادٕ بادشاہس نِش جمع تہٕ وونُکھ أمِس بادشاہ داریوس، ہمیشہٕ زندٕ۔ {جمع...: یا، آو ہنگامہ آرائی}\n7. سلطنتٕکۍ تمام صدر، گورنرن تہٕ شہزادن، مشیرن تہٕ کپتانو چُھ اِکہٕ وٹہٕ شٲہی قانون قٲیم کرنہٕ خٲطرٕ مشورٕ کورمُت، تہٕ اکھ پختہ حکم دِنہٕ خٲطرٕ، زِ یُس تہٕ کُنہِ تہِ خدایس یا انسانس ترہن دۅہن خٲطرٕ درخواست منگہِ، اے بادشاہ، سُہ گژھِ شیرن ہٕندِس گۅپھس منز تراونہٕ یُن۔ {حکم: یا، ممانع}\n8.\\tاے بادشاہ، حکم نامہٕ قٲیم کرُن، تہٕ تحریرس پیٹھ کرُن دستخط، یُس نہٕ بدلاونہٕ یُن، یُس نہٕ بدلاوان چُھ، یُس نہٕ بدلاوان چُھ۔{بدلاوُن نہٕ: چالدی، پاس نہٕ}\n9. اَمہِ مۄکھٕ کٔر بادشاہ داریوَن تحریرس تہٕ فرمانس پیٹھ دستخط۔\n10.\\tوۅنۍ ییلہ دانیالس پتاہ زِ تحریرس پیٹھ چھہ دستخط سپدان، سہ گوٚو پننس گرس منز۔ تہٕ یروشلمس کُن تٔمۍ سٕندِس کمرس مَنٛز دٲر یلہٕ آسنہٕ کِنۍ، سُہ اوس دۅہس منز تریہ لٹہِ کۅٹھن پیٹھ بٔنِتھ، تہٕ دُعا کران تہٕ پننِس خدایس برونہہ کُن شُکر ادا کٔرُن۔\n11. پَتہٕ گٔیہِ یِم نفر جمع تہٕ وُچھُکھ دانیال پننِس خداہس برونہہ کُن دُعا کران تہٕ دُعا کران۔\n12. پتہٕ آیہِ تِم نزدیک، تہٕ بادشاہ سٕندِس حکمس مُتعلِق کٔرٕکھ بادشاہس برونہہ کُن۔ کیا ژے چُھہ نہٕ کُنہِ حکمس پیٹھ دستخط کورمُت، زِ پریتھ کانہہ شخص یُس ترہن دۅہن اندر کٲنٛسہِ خدایہ یا انسانس سٍتۍ درخواست منگِ، اے بادشاہ، سُہ گژھہِ شیرن ہٕندِس گۅپھس منز تراونہٕ یُن۔ بادشاہن دیُت جواب تہٕ وونُن، یہٕ چیز چُھ صحیح، میدس تہٕ فارسین ہٕندِ قانونس مطٲبق، یُس نہٕ بدلان چُھ۔\n13.\\tتێلہِ دِژ تِمو جواب تہٕ وونُن بادشاہس برونہہ کُن، زِ دانیال، یُس یہوداہ کِس قٲد کِس بچیو منزٕ چُھ، چُھہ نہٕ تۅہہِ ہُند خیال تھاوان، اے بادشاہ، تہٕ نہ چُھہ تتھ فرمانس سٍتـ̡ یُس ژے دستخط کورمُت چُھ، بلکہ چُھہ دۅہس منز تریہ لٹہِ تٔمۍ سٕنز عرضی دِوان۔\n14.\\tتمہِ پتہ ییلہ تٔمۍ یہ لفظ بوزِ، سُہ گوٚو پانس سٍتـ̡ ناراض، تہٕ کوٚرُن دِل دانیالس کُن دِل تہٕ تٔمۍ کٔر أمِس نجات دِنہٕ خٲطرٕ آفتاب لوسنہٕ تام محنت۔\n15.\\tپتہٕ گٔیہِ یِم نفر بادشاہس نِش جمع تہٕ وونُکھ بادشاہس زٲنِتھ زِ اے بادشاہ، زِ میڈس تہٕ فارسِین ہُند قانون چُھ، یُس نہٕ بادشاہ قٲیم کٔرِتھ کانہہ تہِ فرمان تہٕ قانون گژھِ بدلاونہٕ یُن۔\n16. پتہٕ دِژ بادشاہن حُکُم، تہٕ تِمو أنۍ دانیال، تہٕ ترٛٲوِن سٕہہ سٕندِس گۅپھس منٛز۔ {وُن} بادشاہن کٔر کتھ تہٕ وونُن دانیالس زِ تُہند خدا یُس ژے مسلسل عبادت کران چُھ، سُہ کرِ ژے بچاو۔\n17.\\tتہٕ اکھ کٔنۍ آو اننہٕ، تہٕ تھووُن گۅپھ کِس گۅپھس پیٹھ۔ تہٕ بادشاہن کٔر اتھ پننہ دستخطہٕ سٍتۍ، تہٕ پننین آقاؤں ہٕندِ نشانہٕ سٍتۍ مہر۔ زِ دانیالس متعلق گژھہِ نہ مقصد بدلاونہ۔\n18.\\tپتہٕ گوٚو بادشاہ پننِس محلس منز، تہٕ رٲژ گُزٲرِن روزُن، تہٕ تٔمِس نِش گُزٲرِن موسیٖقی ہٕندۍ ساز تہٕ تٔمِس نِش گٔیہِ نِندٕ۔ {آلات...: یا، ٹیبل}\n19.\\tپتہٕ ووت بادشاہ سُلہِ سُلہِ تہٕ درٛاو شیرن ہٕندِس گۅپھس کُن۔\n20. تہٕ ییلہ سُہ گۅپھس پیٹھ آو، تٔمۍ ووٚن دانیالس سٍتـ̡ افسوس زِ بادشاہن کٔر دانیالس کُن کتھ تہٕ وونُن زِ اے دانیال، زندٕ خدایہ سُند بند، کیا تُہند خدا، یُس ژٕ مسلسل خدمت کران چُھ، کیا چُھہ تُہند خدا، یٔمِس سٍتـ̡ ژے شیرن نِش نجات دِنس قٲبل؟\n21.\\tتێلہِ ووٚن دانیال بادشاہس زِ اے بادشاہ، ہمیشہٕ زندٕ۔\n22.\\tمیانہِ خدایہ چھُ پَنُن فرشتہٕ سوزمُت، تہٕ شیرن ہٕنز ٲس بنٛد کٔرمٕژ، یُتھ زن تِمو چُھس نہٕ مےٚ تکلیف دِژمُت، تِکیازِ أمِس برونہہ ٲس مےٚ مَنٛز معصومیت لبنہٕ آمٕژ۔ تہٕ ژے برونہہ کُن تہِ، اے بادشاہ، میہ کٔر نہٕ کانہہ تکلیف ۔\n23. اَمہِ پتہٕ گوٚو بادشاہ أمِس خٲطرٕ سٮ۪ٹھاہ خۄش، تہٕ دِتُن حُکُم زِ تِم نِن دانیال گۅپھِ منزٕ نِنہٕ۔ چنانچہ دانیال آو گۅپھِ منزہ نیبر نیرنہٕ، تہٕ تس آو نہٕ کانہہ تکلیف لبنہٕ، تکیازِ سُہ اوس پننس خدایس پیٹھ یقین تھاوان۔\n24. تہٕ بادشاہن دِژ حُکُم، تہٕ تِمو أنۍ تِم نفر یِمو دانیالس پیٹھ الزام اوس لگٲومُت، تہٕ تِمو ترٛٲوِکھ شیرن ہٕندِس گۅپھس منز، تِمن ہٕندِس شُرِ تہٕ تِہنزن زنانن ہٕندِس گۅپھس منز۔ تہٕ شیرن ٲس تمن پیٹھ مہارت حٲصل کٔرمٕژ، تہٕ تِمن ہٕنزٕ تمام أڈجہِ ٹُکرٕ ٹُکرٕ کٔرِتھ یا ٲسۍ تِم گۅپھ کِس دامنس پیٹھ وٲتِتھ۔\n25. اَمہِ پَتہٕ لیوٗکھ بادشاہ داریوَن سارِنٕے لُکَن، قومن تہٕ زبانن یِم سارِنٕے زمینس مَنٛز روزان چھِ۔ تۅہہِ گژھہِ تسلی دِنۍ۔\n26. بہٕ چُھس اَکھ حکم دِوان زِ میانہِ بادشٲہی ہٕندِس پرٮ۪تھ کُنہِ سلطنتس مَنٛز گژھن انسان دٲنِیال سٕندِس خداہس برونہہ کُن تھرتھران تہٕ خوفزدہ روزُن: کیازِ سُہ چُھ زندٕ خدا تہٕ ہمیشہٕ خٲطرٕ روزُن، تہٕ تٔمۍ سٕنز بادشاہی یُس نہٕ ختم گژھہِ، تہٕ تٔمۍ سٕنز سلطنت روزِ ٲخرس تام۔\n27. سُہ چُھ نجات دِوان تہٕ نجات دِوان، تہٕ سُہ چُھ آسمانس تہٕ زمینس مَنٛز نشانہٕ تہٕ عجائبات کٲم کران، یٔمۍ دانیالس شیرن ہٕندِ طاقتہٕ نِش نجات دِژمٕژ۔ {پاور: چالڈی، اتھہ}\n28.\\tیێلہِ گۆو یہِ دانیال داریوس سٕندِس دورس مَنٛز تہٕ سائرس فارسی سٕندِس دورس مَنٛز ترقی۔","1.\\tبابل کِس بادشاہ بلشزار سٕندِس گۅڈنِکِس ؤریس مَنٛز اوس دانیال سٕندِس بسترس پیٹھ کلہٕ سُند خواب تہٕ وژن: پتہٕ لیوکھ تٔمۍ خواب، {تہٕ} وونُن معاملہٕ ہُند مجموعہٕ۔ {had: Chaldee, saw} {معاملہٕ: یا، الفاظ}\n2.\\tدانیال وۆن تہ وونُن، میہ وُچھ رٲژ پننِس وژنس منز، تہٕ وُچھ اسمانٕکۍ ژۅن واو بٔڈِس سمندرس پیٹھ لڑان۔\n3.\\tتہٕ ژور بٔڈ جانور دراو سمندرٕ منز، یِم اکھ أکِس نِش مختلف ٲسۍ۔\n4.\\tگۅڈنیُک {اوس} شیر ہیوٗ تہٕ تس ٲس عقاب سٕندِ پکھہٕ: میہ وُچھ یوٚت تام تِمن ہٕندِ پکھہٕ تُلنہٕ آمٕتۍ، تہٕ سُہ آو زمینہٕ پیٹھٕ تُلنہٕ، تہٕ کھورِ پیٹھ کھڑا کرنہٕ آمُت، تہٕ انسان سُند دِل آو أمِس دِنہٕ۔ {تہٕ یہ: یا، یتھ سۭتۍ}\n5.\\tتہ وُچھ بیاکھ جانور یُس ریچھ ہیو اوس، تہ سہ اوس اکہ طرفہ تھوٚد تہ اتھ ٲسس منز تریہ رِب تہ تمس دندن درمیان تریہ رِب تہ تِمو ووٚن أمس یتھہ پاٹھۍ ووٚتھ، وۅتھ، واریا ماز کھیوٚو۔ {یہ تھوٚد...: یا، یہ تھوٚد اکھ ڈومینین}\n6.\\tاَمہ پتہٕ وُچھ میہ تہٕ بیاکھ اکھ سٕہہ سٕندۍ پٲٹھۍ، یٔمِس پٔتِس پٔتِس پیٹھ کۅکرِ ہٕندۍ ژور پکھہٕ ٲسۍ۔ أمِس درندٕ تہِ ٲسۍ ژور کلہٕ۔ تہٕ اتھ آو غلبہٕ دِنہٕ۔\n7.\\tامہ پتہ وُچھ میہ رٲژ ہٕندِس وژنس منز، تہٕ وُچھ ژوٗرِم درندٕ، یُس خوفناک تہٕ خوفناک تہٕ سٮ۪ٹھاہ مضبوٗط اوس۔ تہٕ أمِس ٲسۍ ششتٕرٕکۍ بٔڈۍ دند: یہِ اوس کھٮ۪وان تہٕ ٹُکرٕ ٹُکرٕ کٔرِتھ، تہٕ أمِس ٲس امہِ برونہہ کنہِ سارِنٕے درندٕ نِش مختلف آسان۔ تہٕ اتھ ٲسۍ داہ سینگ۔\n8.\\tمیہ وچھ سینگ تہ وچھ یمن منز بیاکھ اکھ لۅکٹ سینگ تہ یمس برونہہ کنہِ گۅڈنچہ لۅتہِ سینگ ٲس تُلنہٕ آمژ، تہٕ وچھ اتھ سینگ منز ٲس انسان سنزن اچھن ہش اچھ، تہٕ اکھ ٲس بٔڈ کتھ کران۔\n9.\\tمیہ وُچھ یوٚت تام تخت تراونہٕ آو، تہٕ زمانن ہُند قدیم بِہتھ، یٔمۍ سُند پلو اوس شینہٕ ہیوٗ سفید، تہٕ تٔمۍ سٕندِس کلُک مس اوس خٲلص ییرٕکۍ پٲٹھۍ: تٔمۍ سُند تخت {اوس} نارس ہیوٗ نار، {تہٕ} تٔمۍ سٕندِ چکرٕ {یِتھ} دزان نار۔\n10.\\tاکھ نار دراو تہٕ دراو تس برونہہ کُن: ساسہٕ بٔدۍ کٔر أمِس خدمت کرنہٕ، تہٕ دَہ ساس لٹہِ دَہ ساس گٔیہِ أمِس برونہہ کُن: فیصلہٕ آو مقرر کرنہٕ، تہٕ کتابہٕ آیہ کھولنہٕ۔\n11.\\tمیہ وُچھ تمہِ وقتہ تِمن عظیم لفظن ہٕنزِ آوازِ سٍتـ̡ یُس ہارن سٍتـ̡ وُچھمُت: میہ وُچھ {حتیٰ کہ} یوتام نہٕ یہِ درندہ مارنہٕ آو تہٕ تٔمۍ سُند لاش تباہ سپُد، تہٕ دزنہٕ آمُت نارس دِنہٕ۔\n12.\\tباقٕے درندَن ہُند تعلق چھُ تِمن ہُند سلطنت نِنہٕ آمُت، توتہِ گٔیہِ تِہٕنزِ زندگی أکِس وقتس تہٕ وقتس تام۔ {تہنز زندگی...: چالڈی، زندگی ہند طوالت آو تمن دِنہٕ}\n13.\\tمیہ وُچھ رٲژ ہٕندِس وژنس منز، تہٕ وُچھ یُس انسان سٕندِ نیچو ہٕندۍ پٲٹھۍاسمانُک اوٚبر ہٮ۪تھ آو تہٕ ووت قدیم زمانس منز، تہٕ تِمو أنۍ أمِس برونہہ کُن۔\n14. تہٕ أمِس دِژ سلطنت، تہٕ جلال تہٕ اکھ بادشاہی، یُس سارِنٕے لوک، قومن تہٕ زبانہٕ گژھن أمِس خدمت کرنہٕ: تٔمۍ سٕنز سلطنت چھے اکھ ابدی سلطنت، یُس نہٕ ختم گژھہِ، تہٕ تٔمۍ سٕنز بادشاہت یُس نہٕ ختم گژھہِ۔\n15.\\tمیہ اوس دانیال میٲنس جسمس منز غمگسار گومُت، تہٕ میٲنس کلہٕ کین وژنن کٔر میہ پریشان۔ {جسم: چالڈی، شیتھ}\n16.\\tبہٕ ووت تِمو منزٕ أکِس نِش یُس کھڑا اوس، تہٕ پرژھُس أمِس سارِنٕے سارِنٕے ہٕنز حقیقت۔ چنانچہ تمۍ ووٚن میہ چیزن ہنز تشریح زانن۔\n17.\\tیِم بٔڈۍ درندٕ، یِم ژور بادشاہ چھِ، {یِم} زمینہٕ منزٕ پٲدٕ سپدِ۔\n18.\\tمگر خدایہ سٕندِ مُقدس رٔٹِن بادشٲہی تہٕ رٔٹِن ہمیشہٕ خٲطرٕ، ہمیشہٕ خٲطرٕ۔ {زیادٕ...: چالڈی، تھدِ ، یعنی چیز، یا، مقامات}\n19.\\tتیلہ گژھہِ میہ ژوٗرمہِ درندہ سنز حقیقت، یُس سارِوٕے سارِوٕے نِش مختلف اوس، یمۍ سٕندِ دند ششتٕرٕکۍ ٲسۍ، تہٕ تٔمۍ سٕندِ کیل ٲسۍ پیتلۍ۔ {یُس} کھیوٚت، ٹُکرٕ ٹُکرٕ کٔرِتھ تہٕ باقیاتس پیٹھ تھپھ کٔرِتھ تھپھ کٔرِتھ۔ {منز...: چالڈی، تمن سارنی منز}\n20.\\tتہٕ تِمو دَہو سینگ یُس تٔمۍ سٕندِس کلس منز اوس، تہٕ بیٛاکھ یُس کھسنہٕ آمُت اوس، تہٕ یٔمِس برونہہ کُن ترے پیوٚو۔ حتیٰ کہ سُہ سینگ یُس أچھ اوس، تہٕ اکھ ٲسس یُس واریاہ بٔڈ کتھ کران اوس، یمۍ سٕنز نظر ٲس پننین سٲتھین کھوتہٕ زیادٕ مضبوط۔\n21.\\tمیہ وُچھ تہٕ امی ہارن کٔر سنتن سٍتۍ جنگ تہٕ تمن خلاف فتح حٲصل۔\n22. یوتام زمانہٕ قدیم آو تہٕ اعلیٰ سٕندِس مقدسین ہُند فیصلہ آو دِنہٕ۔ تہٕ سُہ وقت آو زِ مقدسن ٲس بادشٲہی حٲصل۔\n23. یِتھٕ پٲٹھۍ ووٚن تٔمۍ زِ ژوٗرِم درندٕ آسہِ زمینہِ پیٹھ ژوٗرِم بادشٲہی یُس سارِنٕے بادشٲہی نِش مختلف آسہِ، تہٕ سٲرۍسٕے زمینہٕ کھٮ۪یہِ تہٕ ژٔٹِتھ پھُٹراوِ۔\n24.\\tتہٕ امہِ بادشٲہی منزٕ دَہ سینگ یِم دَہ بادشاہ پٲدٕ سپدِ، تہٕ یِمن پتہٕ یِہُند بیاکھ وُتھُن۔ تہٕ سُہ آسہِ گۄڈنِکہِ نِش مختلف تہٕ سُہ کرِ ترٚے بادشاہن زیر کرنہٕ۔\n25.\\tتہٕ سُہ کرِ اعلیٰ سٕندِس خٕلافس خلاف {عظیم} کلام، تہٕ سُہ کرِ اعلیٰ سٕندِس مُقدِس سٍتـ̡ تھپھ کٔرِتھ، تہٕ سُہ کرِ زمانہٕ تہٕ وقتٕچ تقسیمس تام تٔمۍ سٕندِس اتھس مَنٛز دِنہٕ۔\n26.\\tمگر فیصلہ گژھہِ بِہتھ، تہٕ تِم نِن تٔمۍ سٕنز سلطنت نِن، کھٮ۪نہٕ خٲطرٕ تہٕ ٲخرس تام تباہ کرنہٕ خٲطرٕ۔\n27. تہٕ بادشاہی تہٕ بادشاہی تہٕ بادشاہی ہٕنز عظمت، یِہٕنزِ بادشاہی ہٕنزِ بادشاہی ہٕنزِ دِنہٕ یِیہِ اَکھ ابدی بادشٲہی تہٕ سارِنٕے سلطنتن ہٕنز خدمت تہٕ اطاعت کرنہٕ۔ {ڈومینین: یا، حکمران}\n28. وُنیُک تام چُھ معاملُک اختتام۔ یوٚت تام میہ دانیال سٍتۍ میانہِ فکرِ سٍتۍ گٔیہ میہ واریاہ پریشان تہ میون بُتھ بدلیوو مگر میہ تھوو یہ معاملہ پننس دلس منز۔","1.\\tبادشاہ بیلشزار سٕندِس دورِ حکومتہٕ کِس تریمس ؤریس منز آو میہ اکھ وژن ظٲہر کرنہٕ، {حتیٰ کہِ میہ دانیال سٍتـ̡ تہِ، یُس میہ گۅڈنچہ لٹہِ ظٲہر گوو۔\n2. تہٕ مے وُچھ أکِس وژنس منز؛ تہٕ یہ سپُد ییلہ میہ وُچھ زِ بہٕ اوسُس شوشَن مَنٛز {منز} محلس منز، یُس {چُھ} صوبہٕ ایلام کِس علاقس مَنٛز۔ تہٕ میہ وُچھ أکِس وژنس منز، تہٕ بہٕ اوسُس اُلایی کِس دریاوَس نِش۔\n3.\\tاَمہ پتہٕ تُلِتھ کٔر میہ پنٕنۍ أچھ تُل، تہٕ وُچھمُت دٔریاوس برونہہ کُن اکھ کۅکرِ یٔمِس {زٕ} سینٛگ ٲسۍ، تہٕ {زٕ} سینٛگ {ٲس} تھوٚد۔ مگر اکھ {اوس} بییِس کھوتہٕ زیادٕ، تہٕ تھوٚد آو ٲخری پیٹھ۔ {بییِم: ہیب۔ دوٚیِم}\n4.\\tمیہ وچھ یہ رژھ مغرب کُن تہ شمالس کُن تہ جنوبس کُن پکان۔ یُتھ زن نہ کانہہ درندہ أمس برونہہ کنہِ کھڑا گژھہِ، تہ نہ آسہِ کانہہ تہِ یُس تمۍ سندِ اتھہ منزہ نیبر نیرِتھ۔ مگر تٔمۍ کوٚر پننہ مرضی مطٲبق، تہٕ بنیوو عظیم۔\n5.\\tتہ ییلہ میہ سونچان اوسس، وچھ اکھ ژھاوُل آو مغرب پیٹھہ پورہ زمینہِ پیٹھ تہ لوٚگ نہ زمینس سیتۍ اتھہ: تہ ژھاوُل اوس اچھن درمیان اکھ نمایاں سینگ۔ {اتھہ کٔرۍ...: یا، زمینس منز چھہ نہ کانہہ تہِ اتھہ لگان} {اکھ قٲبلِ ذِکر...: ہیب۔ اکھ ہارن آف وژن}\n6.\\tتہٕ سُہ آو تٔمِس نِش یٔمِس {زٕ} سینگ ٲس، یُس میہ دریاوس برونہہ کنہِ کھڑا وُچھمُت اوس، تہٕ ژوٚل أمِس نِش پننہِ طاقتہٕ کِس غصس منز۔\n7.\\tتہٕ میہ وُچھ سُہ کٔرِتھ أمِس نِش یِوان، تہٕ سُہ آو أمِس کُنہِ ہُند اَتھٕ نِش دِنہٕ یِوان۔\n8.\\tتێلہِ گۆو سُہ ژھاوُل سٮ۪ٹھاہ بوٚڈ تہٕ ییلہ سُہ مضبوط اوس، بۆڈ سینگ پھُٹُن۔ تہٕ امہ مۅکھہ آیہ ژور قٲبلِ ذکر آسمانہ کین ژۅن ہواہن کُن۔\n9.\\tتہٕ یِمو منزٕ دراو أکِس منز اکھ لۄکُٹ سینٛگ، یُس جنوبس کُن تہٕ مشرقس کُن تہٕ خۄشگوار زمینس کُن واریاہ بٔڈ اوس۔\n10.\\tتہٕ یہ گۆو آسمانس سٍتـ̡ بٔڈ۔ تہٕ أمۍ ترٛٲوۍ میزبانن تہٕ ستارن ہٕندۍ کینہہ زمینس پیٹھ، تہٕ تمن پیٹھ ٹھپہ لگٲوٕن۔ {میزبانس تام: یا، میزبانس خلاف}\n11.\\tآ، تٔمۍ کٔر میزبان سٕندِس شہزادس تام تہِ بٔڈِتھ تہٕ أمۍ سٕندِ دٔسۍ دِژ روزانہٕ {قربانی} نِنہٕ، تہٕ تٔمۍ سٕندِس مقدس مقامس ہٕنز جاے آیہ تراونہٕ۔ {to: یا، خلاف} {تٔمۍ سٕندِ ذریعہٕ: یا، أمِس نِش}\n12.\\tتہٕ دِیُت اکھ میزبان دِنہٕ آمُت تہٕ أمۍ دِژ حقیقتس زمینس پیٹھ۔ تہٕ أمۍ کٔر عمل، تہٕ ترقی۔ {اکھ میزبان...: یا، میزبان آو دوہ دِنہٕ خٲطرٕ دِنہٕ آمُت}\n13.\\tاَمہ پَتہٕ بوز میہ أکِس درویش سٕنز کتھ تہٕ بییِس درویش سٍتـ̡ وونُن یُس دۅہٕ {قربانی} تہٕ ویرٲنی ہٕندِس خلاف ورزی سٍتـ̡ کُس کالس روزِ، یُس مقدس تہٕ میزبان دۅشوے قدمن تل لَتہٕ دِنہٕ یِنہٕ خٲطرٕ؟ {یہ...: یا، رازن ہند نمبرر، یا، حیرت انگیز نمبرر: ہیب۔ پالمونی} {of...: یا، ویران بناوُن}\n14.\\tتہٕ تٔمۍ ووٚن میہ زٕ ساس تریہ ہتھ دۅہن تام۔ تیلہ گژھہِ مقدس خانہٕ صاف کرنہٕ۔ {دۅہ: ہیب۔ شامُک صبح} {صاف: ہیب۔ جواز دِنہٕ آمُت}\n15.\\tتہ سپد ییلہ میہ {حتیٰ کہ} میہ دانیال یہ وژن وُچھمُت تہ معنی ژھانڈان اوس، تیلہِ وچھ میہ برونہہ کنہِ اکس انسان سُند ظہور پٲٹھۍ۔\n16.\\tتہٕ بوز میہ اُلایی کِس بٹھس درمیان أکِس شخصہٕ سٕنز آواز، یٔمۍ بُلٲوِتھ ووٚنمُت تہٕ وونُن، جبرائیل، یہ {انسان} بناو وژن سمجھنہٕ خٲطرٕ۔\n17. تہٕ سُہ آو ییتہِ بہٕ کھڑا اوس، تہٕ ییلہ سُہ آو بہٕ کھوژمُت، تہٕ پیوٚو پننِس بُتھِس پیٹھ، مگر تٔمۍ ووٚن مے سمجُن، اے انسان سٕندِس نیٚچوِس، کیازِکہِ ٲخرس پیٹھ گژھہِ وژن۔\n18.\\tوۅنۍ ییلہ سہ میہ سیتۍ کتھ کران اوس، میہ اوس بُتھس پیٹھ زمینس کُن شوٚنگتھ مگر تمۍ کٔر میہ تھپھ تہ تھوٚد تھوٚد۔ {سیٹ...: ہیب۔ میہ کٔر پننس مقامس پیٹھ کھڑا کرنہٕ}\n19.\\tتہٕ وۆنُن، وُچھِو بہٕ ژے زانان زِ غصہٕ کِس ٲخری اندس مَنٛز کیا آسہِ، تکیازِ مُقرر کرنہٕ آمُت وِزِ سپدِ ٲخرٕ۔\n20.\\tیُس ژے {زٕ} سینگ وُچھمُت چھُ، سُہ چھُ میڈیاہُک تہٕ فارسُک بادشاہ۔\n21.\\tتہٕ کھردرا ژھاوُل {چُھ} یوناکُک بادشاہ: تہٕ سُہ بٔڈ سینگ یُس تٔمۍ سٕندِس أچھن مَنٛز {چُھ} چُھ گۄڈنیُک بادشاہ۔\n22.\\tوۅنۍ ییلہ ژۅن بادشاہتن ہٕندِ خٲطرٕ کھڑا گٔیہِ، ژۅن بادشاہتن گژھن قومہٕ منز، مگر تٔمۍ سٕندِس اختیارس منز نہٕ۔\n23.\\tتہٕ تِہٕنزِ بادشاہی ہٕندِس ٲخری وقتس منز، یێلہِ نافرمان پورٕ سپدِ، سُہ گژھہِ اکھ زبردست بادشاہ تہٕ سیاہ جملہٕ سمجِتھ کھڑا سپدِ۔ {are...: Heb. مُکمل گَژھنہٕ آمُت}\n24. تہٕ تٔمۍ سُند طاقت آسہِ طاقتور، مگر پننہِ طاقتہٕ سٍتـ̡ نہٕ: تہٕ سُہ کرِ حیرت انگیز طور تباہ تہٕ ترقی تہٕ عمل کرِ، تہٕ طاقتور تہٕ مقدس لوکن کرِ تباہ ۔ {مقدس...: ہیب۔ مُقدسن ہٕندِ لوُکھ\n25.\\tتہٕ پننہِ پالیسی سٍتۍ تہِ کرِ سُہ پننِس اتھس منز ہنر پھۅلان۔ تہٕ سُہ کرِ پننِس دلس منز بڑاوُن، تہٕ امن سٍتۍ کرِ واریاہ تباہ کرنہٕ: سُہ کرِ شہزادن ہٕندِس شہزادس خلاف تہِ کھڑا ۔ مگر سُہ گژھِ اتھہٕ ورٲے پھُٹُن۔ {امن: یا، خوشحالی}\n26.\\tتہٕ شامُک تہٕ صُبحُک وژن یُس وَننہٕ آمُت چھُ، سُہ چُھ پوٚز پٲٹھۍ، تێلہِ کٔرِو ژے وژنُک بند۔ تکیازِ یہ {روزِ} واریاہن دۅہن تام۔\n27.\\tتہٕ بہٕ گۆو دانیال بیہوش، تہٕ اوسُس بیمار {یقین} دۅہ۔ امہ پتہٕ ووٚتھ بہٕ ووٚتھ، تہٕ کٔرٕن بادشاہ سُند کاروبار۔ تہٕ بہٕ گوس اتھ وژنس پیٹھ حٲران، مگر کٲنسہ اوس نہٕ سمجھ نہٕ۔","1. دارا سٕندِس گۄڈنِکِس ؤریس مَنٛز، اہشورس سُند نیچو، یُس مادن ہٕندِس بُلِس سٍتـ̡ بادشاہ بناونہٕ آو۔ {کُس: یا، یتھ منز سُہ}\n2.\\tپننہِ دورِ حکومتہٕ کِس گۄڈنِکِس ؤریس مَنٛز اوس I دانیال کتابو سٍتـ̡ ؤرین ہُند تعداد سمجھان، یێمہِ سٍتـ̡ خداوند سُند کلام یرمیاہ پیغمبرس تام ووت، زِ سُہ کرِ یروشلم کِس ویرٲنِس مَنٛز ستتھ ؤری پورٕ۔\n3. تہٕ بہٕ چُھس خداوند خداہس کُن پنُن بُتھ تھوومُت، دُعا تہٕ دُعا سٍتـ̡ روزٕ تہٕ بُورٕ تہٕ سوٗر سٍتـ̡ منگنہٕ خٲطرٕ:\n4. تہٕ میہ کٔر خداوند پننِس خداہس سٍتـ̡ دُعا تہٕ کوٚرُن پنُن اقرار تہٕ وونُن، اے خدا، عظیم تہٕ خوفناک خدا، تِمن سٍتـ̡ یُس أمِس محبت کران چُھ، تہٕ تِمن سٍتـ̡ یُس تٔمۍ سٕندِس حکمس پیٹھ عمل کران چُھ، تہٕ تِمن سٍتـ̡ چُھہ عہد تہٕ رحمتُک عمل تھاوُن۔\n5. اسہِ چھُ گۅناہ کورمُت، تہٕ بدکار کورمُت، تہٕ بغاوت کٔرمٕژ، چانہِ حکمو نِش تہٕ فیصلہٕ نِش ہٹِتھ تہِ چھُکھ بغاوت کٔرمٕژ۔\n6. نہ چُھہ اسہِ تہندٮ۪ن بندن ہٕندِس پیغمبرن بوزمُت، یِمو تُہٕندِ ناوٕ سٍتـ̡ سانین بادشاہن، سانین شہزادن تہٕ سانین مٲلن تہٕ سارِنٕے ملکٕکۍ لُکن سٍتـ̡ کتھ کٔرۍ۔\n7. اے خداوند، نیکی چُھہ تۅہہِ سٍتـ̡ ، مگر اسہِ سٍتـ̡ چُھہ بُتھِن ہُند انتشار ، یِتھ کٔنۍ از تہِ چُھہ ۔ یہوداہ کین لوکن تہٕ یروشلم کین بسکینن تہٕ سارنٕے اسرٲیلِس خٲطرٕ، یُس نزدیٖکی تہٕ دوٗر چُھ، تِمن سارِنٕے ملکن مٔنزۍ یِمن تہٕ تِمن ہٕندِس خلاف ورزی کٔرِتھ تہٕ تِمن ہٕندِس خطا کِنۍ تہٕ تِمو چُھ تۅہہِ سٍتـ̡ زیادٕ زیادٕ کٔرمٕژ۔ {تعلق تھاوان...: یا، ژے ہاسٹ}\n8. اے خداوند، اسہِ سٍتـ̡ چُھہ بُتھِ ہُند انتشار، سانین بادشاہن سٍتـ̡، سانین شہزادن تہٕ پننین مٲلن سٍتـ̡ ، کیازِ أسـ̡ چُھہ ژے سٍتـ̡ گۅناہ کورمُت۔\n9.\\tخداوند سٕندِس خداہس سٍتـ̡ چُھہ رحمتـ̡ تہٕ معافی دِژمٕژ، یێلہِ زَن أسـ̡ أسـ̡ أمِس خلاف بغاوت کٔرمٕژ۔\n10. نۂ چُھہ أسـ̡ خداوند سٕندِس خدایہِ سٕنزِ آوازِ ہٕنز اطاعت کٔرمٕژ، یُس تٔمۍ سٕندِس شریعت مُطٲبِق پٔکِتھ پۯاونہٕ آمُت چھُ۔\n11. آ، سارِوٕے اسرٲیلَن چُھ تُہٕندِس قونوٗنٕچ خلاف ورزی کٔرمٕژ، یُتھ زن تُہٕنزِ آوازِ ہٕنز اطاعت کٔرِتھ تہِ چھُنہٕ تُہٕندِس قونوٗنٕچ خلاف ورزی کٔرمٕژ۔ تێمہِ کِنۍ چُھ اسہِ پیٹھ لعنت تراونہٕ آمُت، تہٕ سُہ حلف یُس موسیٰ سٕندِس شریعتس مَنٛز لیکھنہٕ آمُت چُھ، یُس خدا سُند خادم چُھ، کیازِ أسـ̡ چُھ أمِس خلاف گۅناہ کورمُت۔\n12. تہٕ تٔمۍ کٔر پننین کلامَن ہٕنز تصدیق یُس تٔمۍ اسہِ خلاف تہٕ سانین قاضن خلاف کٔر یِمو اسہِ پیٹھ اکھ بٔڈ بُردی دِژمٕژ چھِ، کیازِ سارِنٕے آسمانس تل چُھنہٕ یُتھ یُس یروشلمس پیٹھ کرنہٕ آو۔\n13. یِتھ کٔنۍ زَن موسیٰ سٕندِس شریعتس مَنٛز لیکھنہٕ آمُت چُھ، یہِ سورُے بُرٕ چُھ اسہِ سٍتـ̡ آمُت، توتہِ کٔر نہٕ أسـ̡ خداوند پننِس خداہس برونہہ کُن پنٕنۍ دُعا ، یُتھ أسـ̡ پَنٕنـ̡ گناہ نِش پتھ کٔرِتھ تہٕ تُہٕندِس حقیقتس سمجِتھ ۔ {بنیومُت...: ہیب۔ اِنٹریکٹ أس نہٕ بُتھ وغیرہ}\n14. تێمہِ کِنـ̡ چُھہ خداوند بدی وُچھمُت، تہٕ دِژُن اسہِ سٍتـ̡ سٍتـ̡ بێیہِ سٍتـ̡ پى۪ٹھ\n15. تہٕ وُنۍ، اے خداوند سانہِ خدا، یٔمۍ پنُن قوم طاقتور اتھہٕ سٍتـ̡ مصر کِس سرزمینہٕ منزٕ نیبر کٔرِتھ تہٕ ژے ہٕندِس شہرت حٲصل کٔرِتھ، یِتھ کٔنۍ از تہِ۔ اسہِ چھہ گۅنہہ کورمُت، اسہِ چھہ بدکار کورمُت۔ {گٔٹۍ...: ہیب۔ ژے بنوو اکھ ناو}\n16.\\tاے خداوند، چانہِ سارِنٕے نیکی مُطٲبق، بہٕ چُھس ژے التجا کران زِ چانہِ غصہٕ تہٕ غصہٕ گژھہِ پننہِ شہر، یروشلم، تہٕ تُہند مقدس پہاڑ پۯاوُن، کیازِ سانہِ گۅنہٕ تہٕ سانین آباؤ اجدادن ہٕنزِ بدکاریو خٲطرٕ، یروشلم تہٕ تُہند قوم چُھہ اسہِ اندۍ پکھۍ سارِنٕے خٲطرٕ ملامت بٔنِتھ۔\n17. تێمہِ وۆن، اے سٲنـ̡ خدایہ، پنہٕ نـ̡ خادم سٕنز دُعا تہٕ تٔمۍ سٕنزِ دُعا بوزو، تہٕ پَنُن بُتھ کٔرِو پَنُن بُتھ یُس خداوند سٕندِ خٲطرٕ ویران چھُ۔\n18.\\tاے میانہِ خدایہ، کٔرِو کَن کُن تہٕ بوزو۔ پَنٕنۍ أچھ کھٲلِو، تہٕ وُچھِو سانہِ ویران تہٕ سُہ شہر یُس تُہٕندِ ناوٕ سٍتـ̡ وننہٕ چُھ یِوان: کیازِ أسۍ چھِنہٕ پنٕنۍ دُعا پننہِ نیکی خٲطرٕ تہٕ تۅہہِ برونہہ کُن دُعا پیش کران، بٔلکہِ چُھہ چانہِ عظیم رحمتہٕ خٲطرٕ۔ {کُس...: ہیب۔ ییمہ سٍتـ̡ چُھہ تُہند ناو وننہٕ آمُت} {موجود: Heb. گرنُک وجہ}\n19. اے خداوند، بوزو۔ اے خداوند، معافی دِیُن؛ اے خداوند، بوزو تہٕ کر۔ اے خدایہ، پننہِ خاطرہ مہ کرو نہ موخر، تکیازِ تہند شہر تہٕ تہند لوکھ چھہِ تۅہہِ ہندِ ناوٕ سٍتۍ وننہ یوان۔\n20. تہٕ یێلہِ بہٕ کتھ کٔرِتھ، دُعا کٔرِتھ، تہٕ پنُن گۅناہ تہٕ پننین لوکن ہٕندِس گۅناہ ہُند اقرار کٔرِتھ، تہٕ پننِس خدایہ سٕندِس مقدس پہاڑس خٲطرٕ پنُن دُعا پیش کران اوسُس۔\n21.\\tآ، ییلہ بہٕ دعاہس منز کتھ کران اوس، سُہ انسان جبرائیل، یُس میہ گۅڈہ وژنس منز وُچھمُت اوس، سہ تہِ اوس میہ شامٕچ قربان کرنہٕ وِزِ میہ اتھہ تھاوان۔ {تیزی سان: ہیب۔ تھکاوٹ سٍتۍ، یا، پرواز سٍتۍ}\n22.\\tتہٕ تٔمۍ دِژ میہ سٍتـ̡ خبر تہٕ کٔرٕن میہ سٍتـ̡ کتھ تہٕ وونُن، اے دانیال، بہٕ چُھس وۅنۍ ژے ہُنر تہٕ سمجھ دِنہٕ خٲطرٕ برونہہ کُن آمُت۔ {to...: Heb. تۅہہ ہنرمند بناونہٕ خٲطرٕ}\n23. چانہِ دُعا کِس آغازس پیٹھ آو حکم برونہہ کُن، تہٕ بہٕ آو ژے ہاونہٕ خٲطرٕ۔ تکیازِ تۅہہ چھہ واریاہ محبوب: لہذا کرو معاملہ سمجُن، تہٕ وژنس پیٹھ غور کرُن۔ {حکم: حب۔ لفظ} {واریاہ زیادٕ...: ہیب۔ خواہشَن ہُند انسان}\n24. تہندِس لوکَس تہٕ تُہٕندِس مقدس شہرس مَنٛز چُھ ستتھ ہفتہٕ مقرر کرنہٕ آمُت، گُناہ ختم کرنہٕ خٲطرٕ، گۅنہٕ ختم کرنہٕ خٲطرٕ، بدکٲری خٲطرٕ صلح کرنہٕ خٲطرٕ، تہٕ ابدی نیکی حٲصل کرنہٕ خٲطرٕ، تہٕ وژن تہٕ پیشن گویی ہٕنز مہر لگاونہٕ خٲطرٕ، تہٕ مقدس سُند مسح کرنہٕ خٲطرٕ۔ {ختم: یا، پابندی} {بَنٲوِو اَن...: یا، مُہر کَرُن} {پیشن گوئی: ہیب۔ پیغمبر}\n25.\\tتێلہِ زانِو تہٕ سمجُن، {یہ} یُس یروشلم بحال کرنُک تہٕ تعمیر کرنُک حکم برونہہ کُن نیرُن، یُس مسیح سٕندِس سٍتـ̡ سَتھ ہفتہٕ تہٕ تریہ ہفتہٕ تہٕ زٕ ہفتہٕ آسہِ، سڑکہِ ییہ دُبارٕ تعمیر کرنہٕ، تہٕ دیوار ییہِ مصیبت مَنٛز تہِ۔ {بِلٹ کرُن...: ہیب۔ واپس تہٕ بَناوُن} {wall: or, breach, or, ditch} {troublous: Heb. آبنائے آف }\n26. تہٕ تریہ ہتھ تہٕ دون ہفتو پَتہٕ یِیہِ مسیح ژٹنہٕ، مگر پانس خٲطرٕ نہٕ: تہٕ یُس یِنہٕ وٲلِس شہزادٕ سٕندِ لُکھ شہر تہٕ مقدس مقامس تباہ کرُن۔ تہٕ اَمیُک اختتامُک {گژھہِ} سٔہلاب سٍتۍ، تہٕ جنگہٕ کِس اختتامس تام چُھ ویرانین ہُند تعین کرنہٕ آمُت۔ {مگر...: یا، تہٕ آسہِ نہٕ کیٚنٛہہ} {ویرانی...: یا، یہ گژھہِ ویران گژھن ژٹنہٕ}\n27. تہٕ سُہ کرِ أکِس ہفتس تام واریاہن سٍتـ̡ عہد پٲٹھـ̡ تہٕ ہفتس مَنٛز کرِ سُہ قربانی تہٕ نذرانہ بند کرُن، تہٕ مکروہ سپدِتھ کرِ سُہ ویران کرُن، یێلہِ تام تہٕ یُس طے کرنہٕ آمُت آسہِ۔ {معاہدٕ: یا، اکھ معاہدٕ} {امہ خاطرہ...: یا، قابل نفرت فوجن سۭتۍ} {ویران: یا، ویرانی}","1.\\tفارس کِس بادشاہ سائرس سٕندِس تریمس ؤریس منز آو دانیالس نِش اکھ چیز ظٲہر کرنہٕ، ییمِس ناو بلتیشزار ناو اوس وننہٕ۔ تہٕ چیز اوس صحیح، مگر مقرر وقت {اوس} زیوٹھ: تہٕ سُہ اوس چیزس سمجھان، تہٕ وژنُک سمجُن۔ {زیٹھ: ہیب۔ عظیم}\n2. تمن دۅہن اوس میہ دانیال پورٕ تریہ ہفتن پیٹھ ماتم کران۔ {پور...: ہیب۔ ہفتہٕ دۅہہ}\n3.\\tمیہ کھیوٚو نہ کانہہ خۅش روٹی، نہ اوس ماز تہٕ نہ شراب، نہ کٔر میہ پانس مسح کرنہ، یوٚت تام پورٕ تریہ ہفتہٕ پورٕ سپدۍ۔ {خوشگوار...: ہیب۔ خواہشَن ہٕنٛز روٹی }\n4.\\tتہٕ گۅڈنچہ ریتہ کس ژورمہِ تہ وُہمہِ دۅہس منز، ییلہ بہٕ عظیم دریاو کِس بٹھس پیٹھ اوسس، یُس {چھُ} ہڈیکیل۔\n5.\\tاَمہ پتہٕ کٔر میہ پنٕنۍ أچھ تُلِتھ تہٕ وُچھمُت أکِس شخٕصس یُس کُنہِ لٔگِس لٲگِتھ اوس، یٔمۍ سٕندِس لٔگِس سٍتـ̡ اُفازُک سۄنہٕ لٲگِتھ اوسُس: {a...: Heb. اکھ نفر}\n6.\\tتٔمۍ سُند جسم تہِ اوس بیرل ہیوٗ تہٕ بُتھ اوس بجلی ہُند ظٲہر، تہٕ تٔمۍ سٕنزِ أچھ ٲس نارٕچ شمعہٕ ہٕندۍ پٲٹھۍ، تہٕ تٔمۍ سٕنزِ نٔر تہٕ کھۅر ٲس پالش کٔرِتھ پیتل ہٕندۍ پٲٹھۍ، تہٕ تٔمۍ سٕندٮ۪ن کلامَن ہٕنز آواز ٲس بٔڈِس ہٕنزِ آوازِ ہٕندۍ پٲٹھۍ۔\n7. تہٕ میہ وُچھ صرف دانیال وژن: یُس میہ سٍتـ̡ اوس، تِمن وُچھ نہٕ وژن۔ مگر تِمن پیٹھ آو اکھ زبردست زلزلہٕ، تہ تِم ژٔلِتھ ژٔلِتھ۔\n8. تێمہِ کِنۍ اوسُس بہٕ کُنی زُن، تہٕ وُچھمُت یہِ بٔڈ وژن، تہٕ میٲنس مَنٛز روٗد نہٕ کانہہ طاقت: تکیازِ میانہِ خوبصورتی ٲس پانس منز بدعنوانی بنیمٕژ، تہٕ بہٕ روٗد نہٕ کانہہ طاقت۔ {خوبصورتی: یا، زور}\n9.\\tتوتہِ بوز میہ تسٕنزِ کلامٕچ آواز: تہٕ ییلہ میہ تٔمۍ سٕندِ کلامٕچ آواز بوز، تیلہِ اوسُس بہٕ سٕندِس بُتھِس پیٹھ شوٚنگتھ تہٕ بُتھ زمینس کُن۔\n10.\\tتہِ وُچھ اَکھ اَتھٕ یُس میہ کۅٹھن پیٹھ بٔرِتھ تہٕ اَتھن ہٕندِس اتھس پیٹھ تھپھ کٔرِتھ۔ {سیٹ: ہیب۔ منتقل کٔرِتھ}\n11. تہٕ تٔمۍ ووٚن میہ اے دانیال، اے سٮ۪ٹھاہ محبوب انسان، تِم لفظ سمجِو یُس بہٕ ژے کتھ کران چھُ، تہٕ کھڑا کھڑا گژھُن، تکیازِ بہٕ چُھس وُنۍ ژے خٲطرٕ سوزنہٕ آمُت۔ تہٕ ییلہ تٔمۍ یہ لفظ میہ سیتۍ کتھ کٔر، بہٕ اوسس تھرتھر تھران۔ {واریاہ زیادٕ...: ہیب۔ خواہشاتن ہُند} {سید: ہیب۔ تُہٕندِس کھڑس پیٹھ}\n12.\\tتێلہِ ووٚن میہ زِ خوفزدہ گژھ نہ، دانیال، تکیازِ گۅڈنچہ دۅہہ ییلہ ژے پنُن دِل سمجھنہٕ خٲطرٕ تہٕ پننِس خدایس برونہہ کُن پان سزا دِنہٕ خٲطرٕ دِل دِژ، تێلہِ آو تُہند کلام بوزنہٕ، تہٕ بہٕ چُھس چانہِ کلامَن ہٕندِ خٲطرٕ آمُت۔\n13.\\tمگر سلطنت فارس ہُند شہزادٕ روٗد میہ اکہِ تہٕ وُہن دۅہن مُقابلہٕ: مگر لو، مائیکل یُس اکھ اہم شہزادہ اوس، آو میانہِ مدتھ کرنہِ۔ تہٕ بہٕ روٗد تتہِ فارس کین بادشاہن سٍتۍ۔ {چیف: یا، گۄڈٕنِک}\n14. وُنہِ چُھس بہٕ ژےٚ یہِ زاننہٕ خٲطرٕ آمُت زِ پٔتِمِس دۅہس مَنٛز کیا سپدِ تُہندین لوکن سٍتـ̡ ، کیازِ وُنہِ تہِ چُھہ {واریہ} دۅہن پیٹھ۔\n15.\\tتہٕ ییلہ تٔمۍ میہ یِتھۍ لفظ کٔرۍ، میہ تھوو پنُن بُتھ زمینس کُن، تہٕ بہٕ گونگ۔\n16.\\tتہٕ وُچھ، یِتھٕ پٲٹھـ̡ انسانن ہٕندِس نیچوَن ہٕندِس مِثالس سٍتـ̡ چُھس میٲنس چپَس تھپھ کٔرِتھ، تہٕ وونُن یُس میہ برونہہ کُن کھڑا اوس، اے میانہِ آقا، یێلہِ وُچھِتھ چُھس میٲنۍ غم پانس کُن پھیرِمُت، تہٕ بہٕ چُھس نہٕ کانہہ طاقت برقرار تھاوان۔\n17. یێمہِ سُند خادم کِتھہ کٔنۍ ہیکہِ میٲنِس آقا سٍتـ̡ کتھ کٔرِتھ؟ تکیازِ میانہِ خاطرہ چھہ نہ سیدِ سیود میہ منز کانہہ طاقت تہ نہ چھہ میہ منز دم رودمت۔ {the...: یا، میانہِ آقا سُند یہ خادم}\n18.\\tپَتہٕ آو دُبارٕ تہٕ کوٚرُن میہ اِنسان سٕندِ ظہورٕکۍ پٲٹھۍ، تہٕ تٔمۍ کٔر مےٚ مضبوٗط،\n19.\\tتہٕ وونُن، اے انسانہٕ سٍتـ̡ پیاری، خوفہٕ نہٕ کھوژُن: اَمن سٍتـ̡ روزُن، مضبوط روزُن، آ، مضبوط روزُن۔ تہٕ ییلہ تٔمۍ مےٚ کتھ کٔر، بہٕ گٔیہٕ مضبوط، تہٕ وونُن، میانہِ آقا گژھ کتھ کرنہٕ۔ تِکیازِ ژے چُھس میہ مضبوٗط کورمُت۔\n20. اَمہِ پتہٕ ووٚن تٔمۍ زِ ژےٚ چھَے پتاہ زِ بہٕ کیازِ چُھس ژےٚ نِش آمُت؟ تہٕ وۅنۍ گژھٕ بہٕ فارس کِس شہزادس سٍتۍ لڑنہٕ خٲطرٕ واپس: تہٕ ییلہ بہٕ نیرِ، لو، گریسیاہُک شہزادٕ یِیہ۔\n21. مگر بہٕ ہاوٕ ژے سُہ یُس صحیفہٕ کِس صحیفس مَنٛز درج چُھ: تہٕ یِمن چیزن مَنٛز چُھہ نہٕ کانٛہہ تہِ یُس میہ سٍتـ̡ رٔٹِتھ چُھ، مگر میکائیل چُھہ تُہند شہزادٕ۔ {ہولڈتھ: ہیب۔ پنن پان مضبوط کران}","1.\\tمیہ تہِ اوس داریوس میڈ سٕندِس گۅڈنکس ؤریس منز، {حتیٰ کہ} میہ تہِ کھڑا تٔمِس تصدیق کرنہٕ خٲطرٕ تہٕ مضبوٗط کرنہٕ خٲطرٕ۔\n2. تہٕ وۅنۍ ہاوٕ بہٕ ژے حقیقت۔ وُچھِو فارسَس مَنٛز وُنہِ تہِ ترےٚ بادشاہ کھڑا گٔژھِتھ۔ تہٕ ژوٗرِم آسہِ سارِنٕے کھۄتہٕ زیادٕ امیر: تہٕ پننہ طاقتہٕ سٍتۍ کرِ سُہ سارِنٕے گرِشیا کِس دٲیرس خٕلاف ہلچل دِوان۔\n3. تہٕ اکھ طاقتور بادشاہ کھڑا گژھہِ، یُس بٔڈۍ سلطنتہٕ سٍتـ̡ حکومت کرِ، تہٕ پننہِ مرضی مُطٲبق کرِ۔\n4. تہٕ ییلہ سُہ کھڑا گژھہِ، تٔمۍ سٕنز بادشاہت گژھہِ پھُٹِتھ تہٕ ییہِ اسمانٕچ ژۅن ہواہن کُن بٲگراونہٕ۔ تہٕ نہ تٔمۍ سٕندِس اولادن تام، تہٕ نہ تٔمۍ سٕندِس سلطنتس مطٲبق یتھ پیٹھ تٔمۍ حکومت کٔر: تکیازِ تٔمۍ سٕنز سلطنت ییہ تُلنہٕ، تمن علاوٕ باقین خٲطرٕ تہِ۔\n5. تہٕ جنوبُک بادشاہ آسہِ مضبوط، تہٕ پنہٕ نِس شہزادن ہُند {اکھ}۔ تہٕ سُہ آسہِ أمِس پیٹھٕ مضبوط، تہٕ روزِ تٔمِس سٍتـ̡ غلبہٕ۔ تٔمۍ سُند سلطنت آسہِ اکھ بٔڈ سلطنت۔\n6. تہٕ ؤری پٲٹھـ̡ گژھن تِم پانس سٍتـ̡ رٔلِتھ رٔلِتھ تکیازِ جنوبٕچ بادشاہ سٕنز کورِ گژھہِ شمالہٕ کِس بادشاہس نِش اکھ معاہدٕ کرنہٕ خٲطرٕ: مگر سُہ روزِ نہٕ نرِ ہُند طاقت برقرار تھاونہٕ۔ نہ گژھہِ سُہ کھڑا روزُن، تہٕ نہ تٔمۍ سٕنز نٔرۍ، مگر سۅ ییہ تراونہٕ، تہٕ یُس أمس أنِتھ اوس، تہٕ یُس أمس زامُت اوس، تہٕ سُہ یُس أمس {یِمَن} زمانس مَنٛز مضبوٗط کٔرِ۔ {شٲمِل...: ہیب۔ پانس سیتۍ وابستہ} {an...: Heb. حقوق} {سُہ یُس پیدٕ چُھ...: یا، یُس أمِس پٲدٕ کوٚر}\n7.\\tمگر تٔمۍ سٕندِس موٗل ہٕندِس أکِس لٔرِس منزٕ کھڑا گژھہِ، یُس لشکر ہٮ۪تھ یِیہ، تہٕ شُمالہٕ کِس بادشاہ سٕندِس قلعس منز اژِہ، تہٕ تِمن خلاف کرِ مُقابلہٕ، تہٕ غلبہٕ روزِ: {منز...: یا، تٔمۍ سٕنزِ جایہ، یا، دفتر}\n8.\\tتہٕ یِمن ہٕندِس دیوتاہن سٍتـ̡ تہٕ رۄپہٕ تہٕ سۄنہٕ سٕندِس قیمتی بانن سٍتـ̡ نِن قٲد مصرس مَنٛز۔ تہٕ سُہ روزِ شمالہٕ کِس بادشاہس کھوتہٕ زیادٕ ؤری جٲری۔ {تہند قیمتی...: ہیب۔ تہنزِ خواہشکۍ بانہ}\n9.\\tیێلہِ گژھہِ جنوبُک بادشاہ پننہِ سلطنتس مَنٛز، تہٕ گژھہِ پننِس سرزمینس مَنٛز واپس۔\n10.\\tمگر تٔمۍ سٕندِ نیچوۍ گژھن ہلچل دِنہٕ، تہٕ یِن واریاہ بٔڈ فوج جمع کرنہٕ، تہٕ یِیہِ یٔقیٖنی طور یِنہٕ، تہٕ یِیہِ یِمن ہٕندِس قلعس کُن واپس۔ {آسہِ...: یا، جنگ کرُن} {واپس...: یا، بییہِ ہلچل کٔرِو}\n11. تہٕ جنوبُک بادشاہ یِیہِ کولرٕ سٍتـ̡ منتقل کرنہٕ، تہٕ یِیہِ أمِس سٍتـ̡ شُمالہٕ کِس بادشاہس سٍتـ̡ لڑُن، تہٕ سُہ کرِ واریاہ بٔڈ لُکہٕ۔ مگر ہجوم یِن تٔمۍ سٕندِس اتھس منز دِنہٕ۔\n12.\\t{تہٕ}ییلہ سُہ ہجوم نِش نیرِ، تٔمۍ سُند دِل گژھہِ تھوٚد۔ تہٕ سُہ تراوِ دَہ ساس، مگر سُہ گژھِ نہٕ اَمہ سٍتـ̡ مضبوط۔\n13. کیازِ شمالُک بادشاہ گژھہِ واپس، تہٕ کرِ گۅڈنِکہِ کھوتہٕ زیادٕ ہجوم تہٕ یقینا یِیہِ کینژن ؤرین پَتہٕ أکِس بٔڈ لشکر تہٕ واریاہ دولتس سٍتـ̡ یِنہٕ۔ {پتہٕ...: ہیب۔ زمانہٕ کِس ٲخرس پیٹھ، ؤری تہِ}\n14. تہٕ تِمن وقتن منز گژھن واریاہ جنوبٕکِس بادشاہس خلاف کھڑا گژھن: تہٕ تُہٕندِس لوکَن ہٕندِس لُٹنہٕ وٲلِس تہِ گژھن وژن قایم کرنہٕ خٲطرٕ پانس تھزراونہٕ۔ مگر تم گژھن وسن۔ {ڈاکو: ہیب۔ ڈاکوَن ہٕندۍ شُرۍ}\n15.\\tیێلہِ گژھہِ شمالُک بادشاہ یِنہٕ تہٕ اکھ پہاڑ تراوُن، تہٕ سارِوٕے کھۄتہٕ زیادٕ تارٕ دار شہرن پیٹھ قبضہ کرُن: تہٕ جنوبُک ہتھیار گژھن نہٕ برداشت کٔرِتھ، نہ تٔمۍ سٕندِ منتخب لوک، تہٕ نہ گژھہِ کانہہ طاقت تہٕ نہ گژھہِ کانہہ طاقت۔ {ساروٕے کھۄتہٕ زیادٕ...: ہیب۔ گولہ بارود ہُند شہر} {ہس...: ہیب۔ تٔمۍ سٕندِ انتخابٕکۍ لوک}\n16. مگر یُس أمِس خٕلاف ییہِ سُہ کرِ پننہِ مرضی مطٲبق، تہٕ أمِس برونہہ کُن گژھِ نہٕ کانہہ تہِ کھڑا تہٕ سُہ گژھہِ تٔمِس شاندار سرزمینس مَنٛز کھڑا یُس تٔمۍ سٕندِ اتھہٕ سٍتـ̡ کھٮ۪نہٕ ییہِ۔ {شاندار...: یا، خیر بیترِ: ہیب۔ زیورُک سرزمین}\n17.\\tسُہ تہِ کرِ پنُن بُتھ پننہِ پوٗرٕ بادشٲہی ہٕندِس طاقتہٕ سٍتـ̡ اژنہٕ خٲطرٕ، تہٕ پانس سٍتـ̡ سیدِ سٍتـ̡ دٲخل سپدُن۔ یِتھٕ پٲٹھۍ کرِ سُہ تہٕ سُہ دِیہِ أمِس زنانہٕ ہٕنز کورِ، تہٕ کرِ أمِس بد عنوان، مگر سۄ گژھِ نہٕ أمِس سٍتـ̡ کھڑا روزُن، تہٕ نہ آسہِ أمِس خٲطرٕ۔ {سید...: یا، واریاہ سید: یا، برابر حالات} {کرپٹنگ: ہیب۔ کرپٹ کرُن}\n18.\\tامہ پتہ گژھہِ سُہ جزیرن کُن پھیُرُن، تہٕ واریاہ نِن: مگر اکھ شہزادہ کرِ پننہِ طرفہٕ أمِس دِنہٕ آمٕژ ملامت بند کرنہٕ۔ پننہِ ملامت ورٲے کرِ سُہ أمِس کُن پھیرُن۔ {for...: ہیب۔ تٔمِس خٲطرٕ} {ملامت ...: ہیب۔ تٔمۍ سٕنٛز ملامت }\n19.\\tتیلہِ گژھہِ سُہ پَنُن بُتھ پننہِ زمینہٕ کِس قعلس کُن پھیُرُن، مگر سُہ گژھہِ ٹھوکر کھسِتھ پیوٚو، تہٕ لبنہٕ یِنہٕ یِنہٕ۔\n20. تیلہٕ گژھہِ بادشاہی ہٕندِس جلال سٍتـ̡ ٹیکس ہُند اضافہ کرُن، مگر کینژَن دۅہن اندر گژھہِ سُہ تباہ کرنہٕ، نہ غصہٕ سٍتـ̡ تہٕ نہ جنگس منز۔ {اسٹیٹ: یا، جاے} {a...: Heb. اکھ یُس اکس اپارِ نیران چھُ} {غصہ: حب۔ غصہٕ}\n21.\\tتہٕ تٔمۍ سٕندِس جاگیرس مَنٛز گژھہِ اکھ بدکار شخص کھڑا گژھُن، یٔمِس نہٕ تِم سلطنتُک عزتہٕ دِنہٕ یِن، مگر سُہ گژھہِ امن سان یِنہٕ، تہٕ خوشامد کٔرِتھ کرِ بادشاہت حٲصِل۔ {اسٹیٹ: یا، جاے}\n22. تہٕ سٔہلاب سٕندِ نرِ سٍتـ̡ یِن تِم أمِس برونہہ کُن وُچھِتھ تہٕ پھُٹاونہٕ یِن۔ آ، عہد نامہ ہند شہزادہ تہِ۔\n23.\\tتہٕ أمِس سٍتـ̡ رٔلِتھ کرِ سُہ دھوکہٕ دِنہٕ سٍتـ̡ کٲم کٔرِتھ، تکیازِ سُہ گژھہِ یِنہٕ تہٕ أکِس لۄکٹِس لُکہٕ سٍتـ̡ مضبوط۔\n24. سُہ گژھِ صوبہٕ کِس سارِوٕے کھۄتہٕ موٚٹِس مقامس پیٹھ تہِ امن سان اژُن۔ تہٕ سُہ کرِ سُہ {سُہ} یُس نہٕ تٔمۍ سٕندِس مٲلن تہٕ نہ تٔمۍ سٕندِس مٲلن ہٕندِس مٲلس آسہِ کوٚرمُت۔ سُہ کرِ تمن منز شکار، تہٕ لوٹ تہٕ دولت: {آ}، تہٕ سُہ کرِ پنٕنۍ چال مضبوط گڑھن خلاف پیشن گوئی، کینژس کالس خٲطرٕ۔ {پُر امن...: یا، امن تہٕ چربی وغیرہ} {پیشن گوئی...: ہیب۔ تٔمۍ سٕنٛدِ خیالات}\n25. تہٕ سُہ کرِ پنُن طاقت تہٕ حوصلہٕ جنوبٕکِس بادشاہس خٕلاف أکِس بٔڑِس لشکرس سٍتـ̡ ہُریر۔ تہٕ جنوبُک بادشاہ یِیہِ أکِس واریاہ عظیم تہٕ طاقتور فوجس سٍتۍ جنگہٕ خٲطرٕ تیار کرنہٕ۔ مگر سُہ گژھِ نہٕ کھڑا روزُن: تِکیازِ تِم کرِ أمِس خٕلاف پیشن گویی کرنہٕ۔\n26. آ، یُس تٔمۍ سٕندِس مازُک حصہٕ کھٮ۪وان چُھ، تٔمۍ سُند لشکر گژھہِ ژٔلِتھ تہٕ واریاہ گٔیہِ مارٕ۔\n27. تہٕ یِمن دۄشوٕے بادشاہن ہُند دِل گژھن شرارت کرنہٕ خٲطرٕ، تہٕ تِم گژھن أکِس میزس پیٹھ اپُز بولان۔ مگر یہ گژھہِ نہٕ کامیاب: تکیازِ توتہِ گژھہِ انجام مقرر وقتس پیٹھ۔ {دل: ہیب۔ تہند دل}\n28.\\tتیلہِ گژھہِ سُہ سٮ۪ٹھاہ دولت ہٮ۪تھ پننِس سرزمینس منز واپس۔ تہٕ تٔمۍ سُند دِل آسہِ مقدس عہدس خلاف۔ تہٕ سُہ کرِ {کارنامہٕ}، تہٕ پننِس سرزمینس پیٹھ واپس۔\n29. مقرر کرنہٕ آمتس وقتس پیٹھ گژھہِ سُہ واپس، تہٕ جنوبس کُن یِن۔ مگر یہ گژھہِ نہ گۅڈنِکۍ پٲٹھۍ، یا دویمِس پٲٹھۍ۔\n30.\\tتکیازِ چِتِم سٕندِ جہازٕ یِن أمِس خٕلاف یِنہٕ، تێمہِ مۄکھٕ گژھہِ سُہ غمگسار تہٕ واپس، تہٕ یێلہِ گژھہِ سُہ مُقدس عہدس سٍتـ̡ شرارت کرنہٕ۔ سُہ گژھہِ واپس تہٕ تِمن سٍتـ̡ ذہانت روزِ یُس مقدس عہد ترک کرِ۔\n31.\\tتہٕ ہتھیار گژھن تٔمۍ سٕندِس طرفہٕ کھڑا تہٕ تِم کرِ طاقتُک مقدس مقامہٕ آلودہ تہٕ روزُن دِنہٕ آمُت {قربانی} نِن، تہٕ تِم تھاون سُہ مکروہ یُس ویران بناوان چھُ۔ {maketh...: یا، حیران}\n32.\\tیُس عہدس خلاف بدکار کرُن سُہ کرِ خوشامد سٍتـ̡ بد عنوان: مگر یُس لوکھ پننِس خدایس زانان آسہِ تم گژھن مضبوط تہٕ کرُن۔ {کرپٹ: یا، dissemble کرنُک سبب}\n33.\\tیُس لُکن مَنٛز سمجھان چُھ، تِم گژھن واریہن ہُند حکم دِن: توتہِ گژھن تِم تلوار سٍتـ̡ تہٕ نارٕ سٍتـ̡ ، قید کرنہٕ سٍتـ̡ تہٕ لوُٹنہٕ سٍتـ̡ پۯاوٕنـ̡ ۔\n34.\\tوۅنۍ ییلہ تم پیوٚن، تم گژھن رژھ کھنڈ مدد، مگر واریاہ آسن تمن چاپلوسی سیتۍ ژٹان۔\n35.\\tتہٕ یِمو منزٕ کینہہ سمجھ یِن، یِمن آزماونہٕ خٲطرٕ، تہٕ صاف کرنہٕ خٲطرٕ، تہٕ {تِم} سفید، {حتیٰ کہ} ٲخرس تام: کیازِ {یہ} چُھ وُنہِ تہِ أکِس وقتس خٲطرٕ مُقرر کرنہٕ آمُت۔ {کوشش کٔرِو: یا کوشش کٔرِو}\n36.\\tتہٕ بادشاہ کرِ پننہِ مرضی مُطٲبق۔ تہٕ سُہ کرِ پنُن پان تھزر، تہٕ پرٮ۪تھ خداہٕ سٕندِس خداہس خلاف کرِ حیرت انگیز کتھٕ بولن، تہٕ روزِ توٚت تام روزِ ترقی یوٚت تام نہٕ غصہٕ پوٗرٕ سپدِ۔\n37.\\tسُہ کرِ نہ پننین مٲلن ہٕندِس خدایس سٍتـ̡ تہٕ زنانن ہٕنزِ خواہشس سٍتـ̡ تہٕ نہ کُنہِ تہِ خداہس سٍتـ̡\n38.\\tمگر سُہ کرِ پننِس جاگیرس مَنٛز طاقتن ہٕندِس خدایس یزتھ تہٕ یُس خدایہ یُس نہٕ تٔمۍ سٕندِس مٲلس زانان آسہِ، سُہ کرِ سۄنہٕ تہٕ رۄپہٕ تہٕ قیمتی پتھرو تہٕ خۅش چیزو سٍتـ̡ عزت دِنہٕ۔ {منز...: یا، یوتام خدایہ سٕندِس مقامس پیٹھ کرِ سُہ احترام، آ، سُہ کرِ أکِس خدایہ سٕنز عزت، یُس بیترِ} {اسٹیٹ: یا، سٹیڈ} {فورس: یا، گولہ بارود: ہیب۔ مزیم، یا خدایہ سٕندِ محافظ} {خوشگوار: حب۔ مطلوبہ چیز}\n39. یِتھٕ پٲٹھۍ کرِ سُہ أکِس عجیب خداہس سٍتـ̡ مضبوٗط مقامس مَنٛز، یٔمِس سُہ تسلیم کرِ {تہٕ} جلال سٍتـ̡ ہُرراوُن: تہٕ سُہ کرِ تِمن واریاہن پیٹھ حکوٗمت، تہٕ کرِ زمینہٕ فٲیدٕ خٲطرٕ تقسیم۔ {زیادٕ...: ہیب۔ گولہ بارود ہند قلعہ} {gain: Heb. اکھ قیمت}\n40. تہٕ اند واتنہٕ وِزِ گژھہِ جنوبُک بادشاہ أمِس کُن دھکہٕ دِنہٕ: تہٕ شمالُک بادشاہ گژھہِ أمِس خلاف واوٕکۍ پٲٹھۍ، رتھَن تہٕ گُرۍ سوارِ سٍتۍ، تہٕ واریہن جہازن سٍتۍ۔ تہٕ سُہ گژھہِ ملکن منز اژُن، تہٕ بہٕ بہٕ تہٕ نیرِ۔\n41. سُہ تہِ گژھہِ شاندار زمینس مَنٛز اژُن، تہٕ واریاہ {ملک} یِن ختم کرنہٕ، مگر یِم گژھن تٔمۍ سٕندِ اتھہٕ نِش ژلنہٕ، حتیٰ کہِ ادوم تہٕ موآب تہٕ عمون کین بچن ہُند سردار۔ {شاندار...: یا، خیر بیترِ: ہیب۔ لذتُک سرزمین، یا، زیور}\n42.\\tسُہ کرِ ملکن پیٹھ تہِ اتھہٕ پھٔہلاونہٕ، تہٕ مصرٕچ سرزمین گژھہِ نہٕ ژلنہٕ۔ {سٹریچ...: ہیب۔ سوزُن}\n43.\\tمگر تس آسہِ سۅنہٕ تہٕ رۄپھ ہٕندِس خزانس تہٕ مصر کین سارنٕے قیمتی چیزن پیٹھ تہٕ لیبیا تہٕ ایتھوپیا ہٕندِس قدمن پیٹھ آسن۔\n44.\\tمگر مشرق تہٕ شمالہٕ کِنۍ خبر دِیہِ أمِس پریشان: لہذا گژھہِ سُہ سٮ۪ٹھاہ غصہٕ سٍتـ̡ تباہ کرنہٕ خٲطرٕ تہٕ واریاہ ژٔٹِتھ دِنہٕ خٲطرٕ۔\n45.\\tتہٕ سُہ کرِ سمندرن درمیان مقدس پہاڑس مَنٛز پننِس محلٕکۍ خیمہ لاگنہٕ۔ توتہِ گژھہِ سُہ پننِس خاتمس تام، تہٕ کانہہ تہِ کرِ نہٕ أمِس مدد۔ {شاندار...: یا، خیر بیترِ: ہیب۔ پاکیزگی ہٕنٛز خوشی ہُنٛد پہاڑ}","1. تہٕ تمہِ وِزِ گژھہِ میکائیل کھڑا یُس تُہندِ لوکن ہٕندِس شُرین ہٕندِ خٲطرٕ کھڑا آسہِ: تہٕ تتہِ گژھہِ مصیبت ہُند زمانہ، یُس نہٕ زانہہ تہِ اوس نہٕ تِمن ہٕندِس زمانس مَنٛز اکھ قوم تہِ: تہٕ تمہِ وِزِ یِیہِ تُہند لوکھ نجات دِنہٕ، یُس کتابہِ مَنٛز لیکھِتھ آسہِ۔\n2.\\tتہٕ یِمو منزٕ واریاہ یِم زمینہِ ہٕندِس میژِ مَنٛز شوٚنگِتھ چھِ، کینہہ گژھن ابدی زندگی خٲطرٕ، تہٕ کینہہ چھِ ابدی حقارت خٲطرٕ بیدار سپدان۔\n3. تہٕ یِم دانا آسن تِم گژھن آسمانٕچ گاش سٍتـ̡ چمکٕنـ̡ تہٕ تِم یِم واریاہن نیکی کُن بدلاوان چھِ یِم ہمیشہ خٲطرٕ ستارن ہٕندۍ پٲٹھۍ۔ {عقلمند: یا، اساتذہ}\n4. مگر ژے اے دانیال، لفظ بند کٔرِتھ تہٕ کتاب بند کرُن، ٲخرس تام تہِ: واریاہ گژھن یور یور تہٕ یور پھیرِن، تہٕ علمس منز ہُرراوُن۔\n5.\\tامہ پتہ وچھ میہ دانیال تہ وچھ بییہ زہ کھڑا، اکھ دریاو کس بٹھس پیٹھ تہ بیاکھ دریاو کس بٹھس پیٹھ۔ {بینک: ہیب۔ lip} {بینک: Heb. لپ}\n6.\\tتہٕ {اَکہ} ووٚن کُن پوشہٕ لٲگِتھ شخٕصس یُس {اوس} دریاو کِس آبس پیٹھ، یُس {اوس} یِمن عجائب ہُند اند واتنس تام کوتاہ کال آسہِ۔ {پیٹھ...: یا، ہیرِ پیٹھ}\n7.\\tتہٕ بوز سُہ شخٕص یُس دریاو کِس آبس پیٹھ اوس، ییلہ تٔمۍ پنُن دٔچھُن اتھہٕ تہٕ کھووُر اتھہٕ اسمانس کُن تُلِتھ تہٕ تٔمِس سٍتـ̡ قَسم کٔرِتھ یُس ہمیشہٕ زندٕ روزان چُھ، یُس کُنہِ وقتس تہٕ ڈۅڈس کالس روزِ۔ تہٕ ییلہ سُہ مقدس لوکن ہُند طاقت پھٔٹِتھ کرِ، یِم سارِنٕے {چیز} گژھن ختم۔ {اکھ وقت...: یا، حصہ}\n8.\\tتہٕ بوزمُت، مگر میہ آو نہٕ سمجھ نہٕ: تیلہِ ووٚن میہ اے خداوند، یِمن {چیزن} ہُند انجام کیا آسہِ؟\n9.\\tتہٕ ووٚن پننہِ وتہِ پٲٹھۍ، دانیال، تکیازِ لفظ {are} چِھ بند تہٕ ٲخرس تام بند کرنہٕ آمٕتۍ۔\n10. واریاہ گژھن پاک کرنہٕ تہٕ سفید، تہٕ آزماونہٕ یِن۔ مگر بدکار کرِ بدکار سٍتـ̡ تہٕ بدکارن منز گژھہِ نہٕ کانہہ تہِ سمجُن۔ مگر دانشمند گژھہِ سمجُن۔\n11. تہٕ یێمہِ وقتہٕ {یُس} روزنامہٕ {قربان} نِنہٕ ییہِ، تہٕ یُس مکروہ بٔنِتھ بناوان چُھ، {اَتھ مَنٛز گژھہِ ساس زٕ ہتھ نَتھ دۅہہٕ﴾۔ {مکروہ کرُن: ہیب۔ مکروہ قایم کرنہٕ خٲطرٕ} {maketh...: یا، حیران}\n12. سُہ چُھ بابرکت یُس انتظار کران چُھ، تہٕ ساس تریہ ہتھ پانژٕ ترہن دۅہن تام واتان چُھ۔\n13.\\tمگر پَنٕنہِ وتہِ پٔکِو ٲخرس تام پَنٕنـ̡ وَتھ {بٔن}، تکیازِ ژے روزُن آرام تہٕ دۅہہٕ کِس ٲخرس پیٹھ روزُن پنہٕ نـ̡ پَنٕنـ̡ سٍتـ̡ کھڑا روزُن۔ {تۅہہِ خٲطرٕ: یا، تہٕ تُہ، وغیرہ}"];
